import { clerkClient } from "@clerk/express";
import {
  db,
  roomBansTable,
  roomKeyEnvelopesTable,
  roomKickCooldownsTable,
  roomMembersTable,
  roomsTable,
  userProfilesTable,
} from "@workspace/db";
import { and, asc, eq, ne } from "drizzle-orm";

const DELETED_ACCOUNT_OWNER = "deleted-account";

export async function deleteAccount(userId: string): Promise<void> {
  await db.transaction(async (tx) => {
    const ownedRooms = await tx
      .select({ roomId: roomsTable.id })
      .from(roomsTable)
      .where(eq(roomsTable.createdBy, userId));

    for (const { roomId } of ownedRooms) {
      const [successor] = await tx
        .select({ userId: roomMembersTable.userId })
        .from(roomMembersTable)
        .where(
          and(
            eq(roomMembersTable.roomId, roomId),
            ne(roomMembersTable.userId, userId),
          ),
        )
        .orderBy(asc(roomMembersTable.joinedAt))
        .limit(1);

      await tx
        .update(roomsTable)
        .set({ createdBy: successor?.userId ?? DELETED_ACCOUNT_OWNER })
        .where(eq(roomsTable.id, roomId));
    }

    await tx
      .delete(roomKeyEnvelopesTable)
      .where(eq(roomKeyEnvelopesTable.userId, userId));
    await tx
      .delete(roomKickCooldownsTable)
      .where(eq(roomKickCooldownsTable.userId, userId));
    await tx
      .delete(roomBansTable)
      .where(eq(roomBansTable.userId, userId));
    await tx
      .update(roomBansTable)
      .set({ bannedBy: DELETED_ACCOUNT_OWNER })
      .where(eq(roomBansTable.bannedBy, userId));
    await tx
      .delete(roomMembersTable)
      .where(eq(roomMembersTable.userId, userId));
    await tx
      .delete(userProfilesTable)
      .where(eq(userProfilesTable.userId, userId));
  });

  await clerkClient.users.deleteUser(userId);
}