import { Sentry } from "./sentry";
import { logger } from "./logger";

// A Svix (Clerk) endpoint signing secret is the literal prefix "whsec_"
// followed by standard base64 for exactly 24 random bytes — 32 base64
// characters, no padding. Anything else fails HMAC verification on every
// delivery, so the shape is worth checking once at startup instead of
// discovering it one rejected webhook at a time.
const SECRET_PREFIX = "whsec_";
const SECRET_BYTE_LENGTH = 24;

export const DEVELOPMENT_SIGNING_SECRET_ENV_VAR =
  "CLERK_WEBHOOK_SIGNING_SECRET";
export const PRODUCTION_SIGNING_SECRET_ENV_VAR =
  "CLERK_WEBHOOK_SIGNING_SECRET_PRODUCTION";

export type ClerkWebhookSecretStatus = "ok" | "missing" | "malformed";

export type ClerkWebhookSecretInspection =
  | { status: "ok"; envVar: string; signingSecret: string }
  | { status: "missing" | "malformed"; envVar: string; detail: string };

/**
 * Name of the environment variable that holds the signing secret for the
 * environment this process is running in. Read at call time so a request or
 * test that changes NODE_ENV is never served with the other environment's
 * secret.
 */
export function getSigningSecretEnvVar(): string {
  return process.env["NODE_ENV"] === "production"
    ? PRODUCTION_SIGNING_SECRET_ENV_VAR
    : DEVELOPMENT_SIGNING_SECRET_ENV_VAR;
}

/**
 * Describes why a configured value cannot be a Svix signing secret, or null
 * when it can. Every description covers shape only — prefix, character count,
 * decoded byte count — and never any part of the value itself.
 */
function findShapeProblem(value: string): string | null {
  if (value.trim() !== value) {
    return "has leading or trailing whitespace";
  }
  if (!value.startsWith(SECRET_PREFIX)) {
    return `is ${value.length} characters with no "${SECRET_PREFIX}" prefix (an endpoint id or portal URL is a common mix-up)`;
  }

  const body = value.slice(SECRET_PREFIX.length);
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(body)) {
    return `is not base64 after the "${SECRET_PREFIX}" prefix`;
  }

  const decoded = Buffer.from(body, "base64");
  // Node's base64 decoder is lenient, so confirm the value round-trips
  // instead of trusting a decode that silently dropped characters.
  if (decoded.toString("base64") !== body) {
    return `is not canonical base64 after the "${SECRET_PREFIX}" prefix`;
  }
  if (decoded.byteLength !== SECRET_BYTE_LENGTH) {
    return `decodes to ${decoded.byteLength} bytes, expected ${SECRET_BYTE_LENGTH}`;
  }

  return null;
}

/**
 * Reads and shape-checks the signing secret for the current environment.
 * Callers get the secret only when it is usable, so a misconfigured value can
 * never reach the verifier and turn into a stream of rejected deliveries.
 */
export function inspectClerkWebhookSigningSecret(): ClerkWebhookSecretInspection {
  const envVar = getSigningSecretEnvVar();
  const value = process.env[envVar];

  if (!value) {
    return { status: "missing", envVar, detail: "is not set" };
  }

  const problem = findShapeProblem(value);
  if (problem) {
    return { status: "malformed", envVar, detail: problem };
  }

  return { status: "ok", envVar, signingSecret: value };
}

/**
 * Startup check: turns a missing or unusable signing secret into one loud
 * signal (error log plus a Sentry issue) rather than a quiet 4xx per delivery.
 * The process keeps serving — webhooks are one feature, not the whole API —
 * and /api/healthz reports the same state for as long as it persists.
 */
export function reportClerkWebhookSigningSecretStatus(): ClerkWebhookSecretInspection {
  const inspection = inspectClerkWebhookSigningSecret();

  if (inspection.status === "ok") {
    logger.info(
      { envVar: inspection.envVar },
      "Clerk webhook signing secret is configured",
    );
    return inspection;
  }

  const message =
    `Clerk webhook signing secret ${inspection.envVar} ${inspection.detail}. ` +
    "Clerk deliveries will be rejected and moderator name syncing will not run until it is fixed. " +
    `Expected "${SECRET_PREFIX}" followed by base64 for ${SECRET_BYTE_LENGTH} bytes.`;

  logger.error(
    {
      envVar: inspection.envVar,
      secretStatus: inspection.status,
      detail: inspection.detail,
    },
    message,
  );
  Sentry.captureMessage(message, "error");

  return inspection;
}
