import { healthAlertStateTable } from "@workspace/db/schema";
import { drizzle } from "drizzle-orm/node-postgres";
import { eq } from "drizzle-orm";
import pg from "pg";
import { logger } from "./logger";
import { sentryEnvironment } from "./sentry";

/**
 * Durable memory for the health monitor's alert cooldown.
 *
 * The cooldown exists so a standing configuration fault files one Sentry
 * issue rather than one per check. Holding it in process memory only made it
 * reset on every restart, so the same fault alerted again on each boot —
 * loudest exactly when a crash loop or a rolling restart makes the issue
 * stream least readable. The database outlives the process and is shared by
 * every instance, so the rule holds across both.
 *
 * Every function here fails open: a store that cannot be reached logs a
 * warning and lets the monitor fall back to its in-process state, because a
 * silenced alert is worse than a duplicated one.
 */

/** The last alert raised for one scope, as the monitor thinks of it. */
export interface DegradedAlertRecord {
  /**
   * The fault's shape. Two alerts with the same fingerprint are the same
   * standing fault; a different one is new information and alerts at once.
   */
  fingerprint: string;
  /** When the alert was raised, in epoch milliseconds. */
  alertedAt: number;
}

/**
 * Row key for the /api/healthz degraded-readiness alert, per environment.
 * Development and production can point at the same database, and Sentry
 * files their issues separately — so a developer restarting a workspace
 * must never be able to talk production's alert out of being raised.
 */
const READINESS_SCOPE = `readiness:${sentryEnvironment}`;

// This pool is deliberately separate from the application pool: only the
// monitor needs a short deadline. Bound both waiting for a connection and
// executing a query so a stalled store cannot stall a Sentry check-in.
const STORE_TIMEOUT_MS = 2_000;
const db = drizzle(
  new pg.Pool({
    connectionString: process.env["DATABASE_URL"],
    max: 1,
    connectionTimeoutMillis: STORE_TIMEOUT_MS,
    query_timeout: STORE_TIMEOUT_MS,
    statement_timeout: STORE_TIMEOUT_MS,
  }),
);

/**
 * Reads the stored readiness alert, or undefined when none is stored or the
 * store cannot be read. Undefined means "alert now": the first alert after a
 * real change must never wait on storage.
 */
export async function readDegradedAlertRecord(): Promise<
  DegradedAlertRecord | undefined
> {
  try {
    const [row] = await db
      .select({
        fingerprint: healthAlertStateTable.fingerprint,
        alertedAt: healthAlertStateTable.alertedAt,
      })
      .from(healthAlertStateTable)
      .where(eq(healthAlertStateTable.scope, READINESS_SCOPE))
      .limit(1);
    if (!row) return undefined;
    return { fingerprint: row.fingerprint, alertedAt: row.alertedAt.getTime() };
  } catch (err) {
    logger.warn(
      { err },
      "Could not read the stored readiness alert; treating it as unset",
    );
    return undefined;
  }
}

/**
 * Stores the readiness alert just raised, so a restart inside the cooldown
 * does not raise it again. A failed write is logged and otherwise ignored:
 * the alert has already gone out, and the in-process cooldown still holds
 * for as long as this process lives.
 */
export async function writeDegradedAlertRecord(
  record: DegradedAlertRecord,
): Promise<void> {
  try {
    const values = {
      scope: READINESS_SCOPE,
      fingerprint: record.fingerprint,
      alertedAt: new Date(record.alertedAt),
    };
    await db
      .insert(healthAlertStateTable)
      .values(values)
      .onConflictDoUpdate({
        target: healthAlertStateTable.scope,
        set: { fingerprint: values.fingerprint, alertedAt: values.alertedAt },
      });
  } catch (err) {
    logger.warn({ err }, "Could not store the readiness alert cooldown");
  }
}

/**
 * Forgets the stored readiness alert once the fault has cleared, so the next
 * regression alerts immediately instead of being swallowed by a cooldown the
 * fixed fault started.
 */
export async function clearDegradedAlertRecord(): Promise<boolean> {
  try {
    await db
      .delete(healthAlertStateTable)
      .where(eq(healthAlertStateTable.scope, READINESS_SCOPE));
    return true;
  } catch (err) {
    logger.warn({ err }, "Could not clear the stored readiness alert");
    return false;
  }
}
