/**
 * How long to wait before asking Clerk again after a failed request, or
 * null when another attempt cannot help.
 *
 * Only rate limiting (429) and Clerk's own server errors (5xx) are worth
 * retrying: any other answer -- "no such account", a rejected key -- is as
 * final as a success. Clerk reports how long to wait in `retryAfter`
 * (seconds) when it throttles; an exponential back-off is the floor, so a
 * missing or zero value still spaces the attempts out.
 */
export function clerkRetryDelayMs(
  error: unknown,
  attempt: number,
): number | null {
  if (typeof error !== "object" || error === null) return null;
  const candidate = error as { status?: unknown; retryAfter?: unknown };
  const status = typeof candidate.status === "number" ? candidate.status : null;
  if (status !== 429 && (status === null || status < 500 || status >= 600)) {
    return null;
  }
  const retryAfter =
    typeof candidate.retryAfter === "number" && candidate.retryAfter >= 0
      ? candidate.retryAfter * 1_000
      : 0;
  return Math.max(retryAfter, 250 * 2 ** attempt);
}
