import type { Server as SocketIOServer } from "socket.io";
import { logger } from "./logger";
import { Sentry } from "./sentry";
import { stopHealthMonitor } from "./healthMonitor";

type ShutdownProcess = Pick<NodeJS.Process, "once" | "exitCode">;
type ShutdownSocketServer = Pick<SocketIOServer, "close">;

export function registerShutdownHandlers(
  processRef: ShutdownProcess,
  socketServer: ShutdownSocketServer,
): void {
  let shutdownStarted = false;

  const shutdown = (signal: NodeJS.Signals): void => {
    if (shutdownStarted) return;
    shutdownStarted = true;
    logger.info({ signal }, "Shutting down server");
    stopHealthMonitor();
    // Socket.IO closes connected clients and then its attached HTTP server.
    socketServer.close((err) => {
      if (err) {
        Sentry.captureException(err);
        logger.error({ err }, "HTTP server shutdown error");
        processRef.exitCode = 1;
        return;
      }
      processRef.exitCode = 0;
    });
  };

  processRef.once("SIGINT", () => shutdown("SIGINT"));
  processRef.once("SIGTERM", () => shutdown("SIGTERM"));
}