import { db, moderationActionsTable, userProfilesTable } from "@workspace/db";
import { and, desc, eq, inArray, lt } from "drizzle-orm";
import { logger } from "./logger";
import { findAccountSnapshot, getAccountSnapshot } from "./accountProfile";
import { clerkRetryDelayMs } from "./clerkRetry";
import { reportModerationHistoryWriteFailure } from "./moderationAlerts";

export type ModerationActionKind =
  | "ban"
  | "restore"
  | "grant-moderator"
  | "revoke-moderator";

export interface ModerationHistoryEntry {
  id: number;
  action: ModerationActionKind;
  actorUserId: string;
  actorUsername: string;
  targetUserId: string;
  targetUsername: string;
  targetEmail: string | null;
  createdAt: string;
}

export interface ModerationHistoryQuery {
  /** Only return actions older than this row id (for "load more" paging). */
  cursor?: number;
  /** Page size, capped at MAX_MODERATION_HISTORY_PAGE_SIZE. */
  limit?: number;
  /** Restrict to actions taken on this account. */
  targetUserId?: string;
  /** Restrict to actions taken by this administrator. */
  actorUserId?: string;
}

export interface ModerationHistoryPage {
  entries: ModerationHistoryEntry[];
  /** Pass as `cursor` to fetch the next page, or null if there are no more. */
  nextCursor: number | null;
}

const DEFAULT_MODERATION_HISTORY_PAGE_SIZE = 50;
const MAX_MODERATION_HISTORY_PAGE_SIZE = 50;

/**
 * How many times the account lookup behind a ban or restore entry is tried
 * before the entry is written from the names already on hand. Recording
 * happens after the administrator has been answered, so waiting out a
 * short throttle costs them nothing.
 */
const MAX_SNAPSHOT_ATTEMPTS = 3;

/** One history row, with the display names already resolved. */
export interface ModerationActionRecord {
  action: ModerationActionKind;
  actorUserId: string;
  actorUsername: string;
  targetUserId: string;
  targetUsername: string;
  targetEmail: string | null;
}

/**
 * Resolves the display names stored alongside a moderation action.
 *
 * Separated from recording so a change that must never go unrecorded --
 * granting or revoking moderator access -- can write its history row in
 * the same database transaction as the change itself, with the Clerk
 * lookups done beforehand rather than inside the transaction.
 *
 * The target is resolved leniently: an account deleted in Clerk after it
 * was granted access still has to be removable, and the history entry then
 * carries its user ID instead of a name.
 */
export async function buildModerationActionRecord(
  action: ModerationActionKind,
  actorUserId: string,
  targetUserId: string,
): Promise<ModerationActionRecord> {
  const [actor, target] = await Promise.all([
    getAccountSnapshot(actorUserId),
    findAccountSnapshot(targetUserId),
  ]);

  return {
    action,
    actorUserId,
    actorUsername: actor.username,
    targetUserId,
    targetUsername: target?.username ?? targetUserId,
    targetEmail: target?.email ?? null,
  };
}

/**
 * Display names for these accounts as this app last stored them.
 *
 * Used when Clerk cannot be reached: the profile table is written whenever
 * a member saves their profile or syncs a device key, so it usually holds
 * the same name the lookup would have returned. A failure here is logged
 * and answered with no names rather than thrown, because the caller can
 * still record the action against the raw user IDs.
 */
async function storedUsernames(
  userIds: string[],
): Promise<Map<string, string>> {
  try {
    const rows = await db
      .select({
        userId: userProfilesTable.userId,
        username: userProfilesTable.username,
      })
      .from(userProfilesTable)
      .where(inArray(userProfilesTable.userId, userIds));
    return new Map(rows.map((row) => [row.userId, row.username]));
  } catch (error) {
    logger.error(
      { err: error, userIds },
      "failed to read stored display names for moderation history",
    );
    return new Map();
  }
}

/**
 * Like buildModerationActionRecord, but it always produces a record.
 *
 * A throttled or unavailable Clerk is retried first, since that clears on
 * its own within a second or two. If the lookup still cannot answer, the
 * record is built from the display names this app has stored for the two
 * accounts, and from their user IDs when even those are unknown. Email is
 * left out in that case rather than guessed at.
 *
 * Only the ban/restore path uses this: those changes have already taken
 * effect, so an unreadable name must not cost the log its entry. Granting
 * and revoking moderator access still uses the strict lookup, because
 * there the change is rolled back when it cannot be audited.
 */
async function buildRecordWithFallbackNames(
  action: ModerationActionKind,
  actorUserId: string,
  targetUserId: string,
): Promise<ModerationActionRecord> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await buildModerationActionRecord(
        action,
        actorUserId,
        targetUserId,
      );
    } catch (error) {
      const delayMs = clerkRetryDelayMs(error, attempt);
      if (delayMs !== null && attempt + 1 < MAX_SNAPSHOT_ATTEMPTS) {
        await new Promise((resolve) => setTimeout(resolve, delayMs));
        continue;
      }

      logger.warn(
        { err: error, action, actorUserId, targetUserId },
        "recording moderation action without a fresh account lookup",
      );
      const usernames = await storedUsernames([actorUserId, targetUserId]);
      return {
        action,
        actorUserId,
        actorUsername: usernames.get(actorUserId) ?? actorUserId,
        targetUserId,
        targetUsername: usernames.get(targetUserId) ?? targetUserId,
        targetEmail: null,
      };
    }
  }
}

/**
 * Records who performed a moderation action (banning or restoring an
 * account), on which account, and when. Display names and email are
 * snapshotted at the time of the action so the trail stays readable even
 * if the account is later renamed or deleted.
 *
 * The action itself has already succeeded by the time this is called, so a
 * failure here is logged and reported to Sentry but never surfaced as a
 * failed request -- otherwise an admin could be misled into retrying an
 * action that already took effect. The alert is what keeps a lost entry
 * from passing unnoticed, since nothing about the request says the audit
 * trail is now incomplete. For the same reason the entry is never dropped
 * just because the account names could not be looked up: an action that
 * happened has to appear in the log, with whatever names are available.
 *
 * Moderator grants and revocations do not use this path: they write their
 * history row in the same transaction as the change, so a privilege change
 * can never end up without an audit entry.
 */
export async function recordModerationAction(
  action: ModerationActionKind,
  actorUserId: string,
  targetUserId: string,
): Promise<void> {
  try {
    const record = await buildRecordWithFallbackNames(
      action,
      actorUserId,
      targetUserId,
    );

    await db.insert(moderationActionsTable).values(record);
  } catch (error) {
    reportModerationHistoryWriteFailure(error, {
      action,
      actorUserId,
      targetUserId,
    });
  }
}

/**
 * Lists moderation history, newest first, with cursor-based paging and
 * optional filtering by target account or acting administrator.
 *
 * Ordering (and the paging cursor) is based on `id` rather than
 * `createdAt`: `id` is a strictly increasing serial column, so it gives an
 * unambiguous order and cursor even when two actions share a timestamp.
 */
export async function listModerationActions(
  query: ModerationHistoryQuery = {},
): Promise<ModerationHistoryPage> {
  const limit = Math.min(
    Math.max(query.limit ?? DEFAULT_MODERATION_HISTORY_PAGE_SIZE, 1),
    MAX_MODERATION_HISTORY_PAGE_SIZE,
  );

  const conditions = [];
  if (query.cursor !== undefined) {
    conditions.push(lt(moderationActionsTable.id, query.cursor));
  }
  if (query.targetUserId) {
    conditions.push(eq(moderationActionsTable.targetUserId, query.targetUserId));
  }
  if (query.actorUserId) {
    conditions.push(eq(moderationActionsTable.actorUserId, query.actorUserId));
  }

  // Fetch one extra row to know whether another page exists without a
  // separate count query.
  const rows = await db
    .select()
    .from(moderationActionsTable)
    .where(conditions.length ? and(...conditions) : undefined)
    .orderBy(desc(moderationActionsTable.id))
    .limit(limit + 1);

  const hasMore = rows.length > limit;
  const page = hasMore ? rows.slice(0, limit) : rows;

  return {
    entries: page.map((row) => ({
      id: row.id,
      action: row.action as ModerationActionKind,
      actorUserId: row.actorUserId,
      actorUsername: row.actorUsername,
      targetUserId: row.targetUserId,
      targetUsername: row.targetUsername,
      targetEmail: row.targetEmail,
      createdAt: row.createdAt.toISOString(),
    })),
    nextCursor: hasMore ? (page[page.length - 1]?.id ?? null) : null,
  };
}
