import { Router } from "express";
import { db, roomBansTable, roomsTable } from "@workspace/db";
import { and, eq, gt, isNull, or } from "drizzle-orm";
import {
  configuredAdminIds,
  isAdmin,
  isConfiguredAdmin,
  setAccountBan,
} from "../lib/accountAccess";
import {
  findAccountSnapshot,
  normalizeAccountSearchQuery,
  searchAccounts,
} from "../lib/accountProfile";
import {
  buildModerationActionRecord,
  listModerationActions,
  recordModerationAction,
} from "../lib/moderationHistory";
import {
  grantModerator,
  isMissingModeratorTable,
  listGrantedModerators,
  revokeModerator,
} from "../lib/moderatorStore";
import { requireAuthorizedUser } from "../lib/requireAccountAccess";
import {
  disconnectBannedUser,
  kickRoomMember,
  kickRoomUser,
  notifyModeratorAccessChanged,
} from "../socket";

/**
 * Where an account's moderator access comes from: `configured` for the
 * ADMIN_USER_IDS bootstrap list (only a configuration change can remove
 * it), `granted` for the database allow-list managed here.
 */
type ModeratorSource = "configured" | "granted";

interface ModeratorListEntry {
  userId: string;
  username: string | null;
  email: string | null;
  source: ModeratorSource;
  grantedBy: string | null;
  grantedAt: string | null;
}

/**
 * Shown when the allow-list table does not exist yet -- the published
 * database gets it when the app is next published. Moderators from
 * ADMIN_USER_IDS keep working meanwhile, so this is a clear explanation
 * rather than an unexplained server error.
 */
const MODERATOR_LIST_UNAVAILABLE =
  "Moderator management is unavailable here until the app is published with the moderator list. Moderators set in the server configuration are unaffected.";

const router = Router();

function makeId() {
  return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

router.get("/search", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }
  const query = normalizeAccountSearchQuery(req.query["query"]);
  if (!query) {
    res.status(400).json({ error: "Enter at least 2 characters to search." });
    return;
  }

  try {
    res.json({ results: await searchAccounts(query) });
  } catch (error) {
    next(error);
  }
});

router.get("/history", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }

  const rawCursor = req.query["cursor"];
  let cursor: number | undefined;
  if (typeof rawCursor === "string" && rawCursor.trim()) {
    const parsed = Number(rawCursor);
    if (!Number.isInteger(parsed) || parsed <= 0) {
      res.status(400).json({ error: "cursor must be a positive integer." });
      return;
    }
    cursor = parsed;
  }

  const targetUserId = req.query["targetUserId"];
  const actorUserId = req.query["actorUserId"];

  try {
    const page = await listModerationActions({
      cursor,
      targetUserId: typeof targetUserId === "string" ? targetUserId.trim() || undefined : undefined,
      actorUserId: typeof actorUserId === "string" ? actorUserId.trim() || undefined : undefined,
    });
    res.json({ actions: page.entries, nextCursor: page.nextCursor });
  } catch (error) {
    next(error);
  }
});

/**
 * GET /api/moderation/moderators
 *
 * Everyone who can moderate right now: the ADMIN_USER_IDS bootstrap list
 * first, then the accounts granted access from this panel. Display names
 * are resolved from Clerk; an id with no matching account is still listed
 * (with no name) rather than hidden, so a stale entry stays visible.
 */
router.get("/moderators", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }

  try {
    const granted = await listGrantedModerators();
    const seen = new Set<string>();
    const entries: ModeratorListEntry[] = [];

    for (const userId of configuredAdminIds()) {
      if (seen.has(userId)) continue;
      seen.add(userId);
      entries.push({
        userId,
        username: null,
        email: null,
        source: "configured",
        grantedBy: null,
        grantedAt: null,
      });
    }
    // An account in both lists is reported as configured: revoking its row
    // would not take its access away, so the panel must not offer that.
    for (const moderator of granted) {
      if (seen.has(moderator.userId)) continue;
      seen.add(moderator.userId);
      entries.push({
        userId: moderator.userId,
        username: null,
        email: null,
        source: "granted",
        grantedBy: moderator.grantedBy,
        grantedAt: moderator.grantedAt.toISOString(),
      });
    }

    const snapshots = await Promise.all(
      entries.map((entry) => findAccountSnapshot(entry.userId)),
    );
    res.json({
      moderators: entries.map((entry, index) => ({
        ...entry,
        username: snapshots[index]?.username ?? null,
        email: snapshots[index]?.email ?? null,
      })),
    });
  } catch (error) {
    if (isMissingModeratorTable(error)) {
      res.status(503).json({ error: MODERATOR_LIST_UNAVAILABLE });
      return;
    }
    next(error);
  }
});

/**
 * POST /api/moderation/moderators
 *
 * Grants moderator access to an existing account. The grant is stored in
 * the database, so it applies from the next request onwards without a
 * configuration change or a republish.
 */
router.post("/moderators", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }
  const rawTargetId = req.body?.["userId"];
  if (typeof rawTargetId !== "string" || !rawTargetId.trim()) {
    res.status(400).json({ error: "userId required" });
    return;
  }
  const targetId = rawTargetId.trim();

  try {
    if (isConfiguredAdmin(targetId)) {
      res.status(409).json({
        error: "That account already moderates from the server configuration.",
      });
      return;
    }
    const account = await findAccountSnapshot(targetId);
    if (!account) {
      res.status(404).json({ error: "No account matches that user ID." });
      return;
    }
    // Resolved before the write so the grant and its history entry are
    // stored together; a grant that cannot be audited is not applied.
    const historyRecord = await buildModerationActionRecord(
      "grant-moderator",
      actorId,
      targetId,
    );
    if (!(await grantModerator(targetId, actorId, historyRecord))) {
      res.status(409).json({ error: "That account is already a moderator." });
      return;
    }
    // Sent only once the grant is stored, so an open copy of that account's
    // app is never told about access a later reload would not find.
    notifyModeratorAccessChanged(targetId, true);

    res.json({ ok: true, username: account.username });
  } catch (error) {
    if (isMissingModeratorTable(error)) {
      res.status(503).json({ error: MODERATOR_LIST_UNAVAILABLE });
      return;
    }
    next(error);
  }
});

/**
 * DELETE /api/moderation/moderators/:userId
 *
 * Revokes a database-granted moderator. Moderators from ADMIN_USER_IDS can
 * only be removed by changing that configuration, and a moderator cannot
 * remove their own last remaining access, so the panel can never be left
 * without anyone able to reach it.
 */
router.delete("/moderators/:userId", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }
  const targetId = req.params["userId"]?.trim();
  if (!targetId) {
    res.status(400).json({ error: "userId required" });
    return;
  }
  if (targetId === actorId && !isConfiguredAdmin(actorId)) {
    res.status(400).json({
      error:
        "You cannot remove your own moderator access. Ask another moderator to remove it.",
    });
    return;
  }
  if (isConfiguredAdmin(targetId)) {
    res.status(409).json({
      error:
        "That account moderates from the ADMIN_USER_IDS configuration and cannot be removed here.",
    });
    return;
  }

  try {
    const historyRecord = await buildModerationActionRecord(
      "revoke-moderator",
      actorId,
      targetId,
    );
    if (!(await revokeModerator(targetId, historyRecord))) {
      res.status(404).json({ error: "That account is not a moderator." });
      return;
    }
    // The removal is stored, so the account's open sessions can drop the
    // controls now rather than waiting for their next re-read of the role.
    notifyModeratorAccessChanged(targetId, false);
    res.json({ ok: true });
  } catch (error) {
    if (isMissingModeratorTable(error)) {
      res.status(503).json({ error: MODERATOR_LIST_UNAVAILABLE });
      return;
    }
    next(error);
  }
});

router.post("/:roomId/kick", async (req, res) => {
  const actorId = await requireAuthorizedUser(req, res);
  const roomId = req.params["roomId"];
  const rawTargetId = req.body?.["userId"];
  if (!actorId) return;
  if (typeof roomId !== "string" || !/^[a-zA-Z0-9_-]{3,64}$/.test(roomId)) {
    res.status(400).json({ error: "A valid room is required." });
    return;
  }
  if (typeof rawTargetId !== "string" || !rawTargetId.trim()) {
    res.status(400).json({ error: "userId required" });
    return;
  }
  const targetId = rawTargetId.trim();

  const result = await kickRoomMember(roomId, actorId, targetId);
  if (result === "ok") {
    res.json({ ok: true });
    return;
  }
  if (result === "room-not-found" || result === "target-not-found") {
    res.status(404).json({ error: "Room member not found." });
    return;
  }
  if (result === "protected-target") {
    res.status(403).json({ error: "Administrators cannot be removed from rooms." });
    return;
  }
  res.status(403).json({ error: "Room creator permission required." });
});

router.post("/:roomId/ban", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  const roomId = req.params["roomId"];
  const rawTargetId = req.body?.["userId"];
  const reason = req.body?.["reason"];
  if (typeof roomId !== "string" || !/^[a-zA-Z0-9_-]{3,64}$/.test(roomId)) {
    res.status(400).json({ error: "A valid room is required." });
    return;
  }
  if (typeof rawTargetId !== "string" || !rawTargetId.trim()) {
    res.status(400).json({ error: "userId required" });
    return;
  }
  const targetId = rawTargetId.trim();

  try {
    const [room] = await db
      .select({ createdBy: roomsTable.createdBy })
      .from(roomsTable)
      .where(eq(roomsTable.id, roomId))
      .limit(1);
    const actorIsAdmin = await isAdmin(actorId);
    if (!room || (room.createdBy !== actorId && !actorIsAdmin)) {
      res.status(403).json({ error: "Room creator or admin required" });
      return;
    }
    if (targetId === actorId) {
      res.status(400).json({ error: "Cannot ban yourself" });
      return;
    }
    if (await isAdmin(targetId)) {
      res.status(403).json({ error: "Administrators cannot be banned from rooms." });
      return;
    }

    const [activeBan] = await db
      .select({ id: roomBansTable.id })
      .from(roomBansTable)
      .where(
        and(
          eq(roomBansTable.roomId, roomId),
          eq(roomBansTable.userId, targetId),
          or(
            isNull(roomBansTable.expiresAt),
            gt(roomBansTable.expiresAt, new Date()),
          ),
        ),
      )
      .limit(1);
    if (activeBan) {
      res.status(409).json({ error: "User is already banned" });
      return;
    }

    const expiresAt = actorIsAdmin
      ? null
      : new Date(Date.now() + 24 * 60 * 60 * 1000);
    await db.insert(roomBansTable).values({
      id: makeId(),
      roomId,
      userId: targetId,
      bannedBy: actorId,
      isPermanent: actorIsAdmin,
      expiresAt,
      reason: typeof reason === "string" ? reason.slice(0, 200) : null,
    });
    await kickRoomUser(roomId, targetId, true);
    res.json({ ok: true, isPermanent: actorIsAdmin, expiresAt });
  } catch (error) {
    next(error);
  }
});

router.post("/ban", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }
  const rawTargetId = req.body?.["userId"];
  if (typeof rawTargetId !== "string" || !rawTargetId.trim()) {
    res.status(400).json({ error: "userId required" });
    return;
  }
  const targetId = rawTargetId.trim();
  if (targetId === actorId || (await isAdmin(targetId))) {
    res.status(403).json({ error: "Administrator accounts cannot be banned." });
    return;
  }

  try {
    await setAccountBan(targetId, true);
    disconnectBannedUser(targetId);
    res.json({ ok: true });
    void recordModerationAction("ban", actorId, targetId);
  } catch (error) {
    next(error);
  }
});

router.delete("/ban/:userId", async (req, res, next) => {
  const actorId = await requireAuthorizedUser(req, res);
  if (!actorId) return;
  if (!(await isAdmin(actorId))) {
    res.status(403).json({ error: "Administrator permission required." });
    return;
  }
  const targetId = req.params["userId"];
  if (!targetId?.trim()) {
    res.status(400).json({ error: "userId required" });
    return;
  }

  try {
    await setAccountBan(targetId, false);
    res.json({ ok: true });
    void recordModerationAction("restore", actorId, targetId);
  } catch (error) {
    next(error);
  }
});

export default router;
