import { clerkClient } from "@clerk/express";
import { db, userProfilesTable } from "@workspace/db";
import { eq } from "drizzle-orm";
import {
  isAccountBanned,
  isConfiguredAdmin,
  type ClerkIdentity,
} from "./accountAccess";
import {
  isProfileAvatar,
  type ProfileAvatar,
} from "./profileAvatars";
import {
  getProfileEmailIdentity,
  isSameProfileEmailIdentity,
  type ProfileEmailIdentity,
} from "./profileIdentity";

const DEFAULT_AVATAR_EMOJI: ProfileAvatar = "🧑‍💻";
const DEFAULT_USERNAME = "Member";
const PROFILE_METADATA_KEY = "devStudioProfile";
const PROFILE_IDENTITY_METADATA_KEY = "devStudioProfileIdentity";
const MAX_ACCOUNT_SEARCH_RESULTS = 8;
const MIN_ACCOUNT_SEARCH_QUERY_LENGTH = 2;

export interface AccountProfile {
  username: string;
  avatarEmoji: string;
}

export async function syncUserPublicKey(
  userId: string,
  publicKey: string,
): Promise<void> {
  const profile = await getAccountProfile(userId);
  await db
    .insert(userProfilesTable)
    .values({
      userId,
      username: profile.username,
      avatar: profile.avatarEmoji,
      publicKey,
    })
    .onConflictDoUpdate({
      target: userProfilesTable.userId,
      set: {
        username: profile.username,
        avatar: profile.avatarEmoji,
        publicKey,
        updatedAt: new Date(),
      },
    });
}
export interface AccountSearchResult {
  userId: string;
  username: string;
  avatarEmoji: string;
  email: string | null;
  banned: boolean;
}

export interface AccountSnapshot {
  userId: string;
  username: string;
  email: string | null;
}

export function normalizeProfileUsername(value: unknown): string {
  if (typeof value !== "string") return DEFAULT_USERNAME;
  const username = value.trim().replace(/\s+/g, " ");
  return username.length >= 2 && username.length <= 30
    ? username
    : DEFAULT_USERNAME;
}

export function normalizeProfileAvatar(value: unknown): ProfileAvatar {
  return isProfileAvatar(value) ? value : DEFAULT_AVATAR_EMOJI;
}

function getRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function fromClerkUser(
  user: ClerkIdentity & {
    username: string | null;
    firstName: string | null;
    privateMetadata: Record<string, unknown>;
  },
): AccountProfile {
  const saved = getRecord(user.privateMetadata[PROFILE_METADATA_KEY]);
  const fallbackName = normalizeProfileUsername(
    user.username ?? user.firstName ?? DEFAULT_USERNAME,
  );
  const savedUsername = normalizeProfileUsername(
    saved?.["username"] ?? fallbackName,
  );
  return {
    username: savedUsername,
    avatarEmoji: normalizeProfileAvatar(saved?.["avatarEmoji"]),
  };
}

function getSavedProfileIdentity(
  privateMetadata: Record<string, unknown>,
): ProfileEmailIdentity | null {
  const saved = getRecord(privateMetadata[PROFILE_IDENTITY_METADATA_KEY]);
  if (
    !saved ||
    !("primaryEmailAddressId" in saved) ||
    !("primaryEmail" in saved) ||
    !("primaryEmailVerified" in saved) ||
    (saved["primaryEmailAddressId"] !== null &&
      typeof saved["primaryEmailAddressId"] !== "string") ||
    (saved["primaryEmail"] !== null && typeof saved["primaryEmail"] !== "string") ||
    typeof saved["primaryEmailVerified"] !== "boolean"
  ) {
    return null;
  }
  return {
    primaryEmailAddressId: saved["primaryEmailAddressId"],
    primaryEmail: saved["primaryEmail"],
    primaryEmailVerified: saved["primaryEmailVerified"],
  };
}

export async function getAccountProfile(
  userId: string,
): Promise<AccountProfile> {
  const user = await clerkClient.users.getUser(userId);
  return fromClerkUser(user);
}

export async function updateAccountProfile(
  userId: string,
  profile: AccountProfile,
): Promise<AccountProfile> {
  const existingUser = await clerkClient.users.getUser(userId);
  const fallbackName = normalizeProfileUsername(
    existingUser.username ?? existingUser.firstName ?? DEFAULT_USERNAME,
  );
  const profileToSave: AccountProfile = {
    username: normalizeProfileUsername(profile.username),
    avatarEmoji: normalizeProfileAvatar(profile.avatarEmoji),
  };
  const privateMetadata: Record<string, unknown> = {
    ...existingUser.privateMetadata,
    [PROFILE_METADATA_KEY]: profileToSave,
  };
  if (isConfiguredAdmin(userId)) {
    privateMetadata[PROFILE_IDENTITY_METADATA_KEY] =
      getProfileEmailIdentity(existingUser);
  }
  const user = await clerkClient.users.updateUserMetadata(userId, {
    privateMetadata,
  });
  return fromClerkUser(user);
}

/**
 * Keeps configured moderators' canonical display names aligned with Clerk
 * after a primary-email identity change. The webhook only supplies a user ID
 * here; fetching the current record prevents delayed/retried events from
 * restoring an older name. Access metadata is never read or modified.
 */
export async function syncModeratorProfileAfterIdentityChange(
  userId: string,
): Promise<void> {
  if (!isConfiguredAdmin(userId)) return;

  const user = await clerkClient.users.getUser(userId);
  const nextIdentity = getProfileEmailIdentity(user);
  const previousIdentity = getSavedProfileIdentity(user.privateMetadata);
  if (previousIdentity && isSameProfileEmailIdentity(previousIdentity, nextIdentity)) {
    return;
  }

  // Existing moderators may predate identity snapshots. Enroll them without
  // treating the first unrelated user.updated event as an email change.
  if (!previousIdentity) {
    await clerkClient.users.updateUserMetadata(userId, {
      privateMetadata: {
        ...user.privateMetadata,
        [PROFILE_IDENTITY_METADATA_KEY]: nextIdentity,
      },
    });
    return;
  }

  const savedProfile = getRecord(user.privateMetadata[PROFILE_METADATA_KEY]);
  const canonicalUsername = normalizeProfileUsername(
    user.username ?? user.firstName ?? DEFAULT_USERNAME,
  );
  await clerkClient.users.updateUserMetadata(userId, {
    privateMetadata: {
      ...user.privateMetadata,
      [PROFILE_METADATA_KEY]: {
        ...savedProfile,
        username: canonicalUsername,
      },
      [PROFILE_IDENTITY_METADATA_KEY]: nextIdentity,
    },
  });
}

/**
 * Snapshot of an account's display name and email at a point in time, used
 * for audit trails (e.g. moderation history) that must stay readable even if
 * the account is later renamed or deleted.
 */
export async function getAccountSnapshot(
  userId: string,
): Promise<AccountSnapshot> {
  const user = await clerkClient.users.getUser(userId);
  const profile = fromClerkUser(user);
  const primaryEmail = user.emailAddresses.find(
    (emailAddress) => emailAddress.id === user.primaryEmailAddressId,
  );
  return {
    userId,
    username: profile.username,
    email: primaryEmail?.emailAddress ?? null,
  };
}

function isAccountNotFound(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    (error as { status?: unknown }).status === 404
  );
}

/**
 * Like getAccountSnapshot, but returns null when Clerk has no such account.
 *
 * Used before granting moderator access so a mistyped or stale user ID is
 * reported as "no such account" instead of being stored as a moderator that
 * nobody can ever sign in as. Any other Clerk failure is rethrown, so a
 * temporary outage is never reported as a missing account.
 */
export async function findAccountSnapshot(
  userId: string,
): Promise<AccountSnapshot | null> {
  try {
    return await getAccountSnapshot(userId);
  } catch (error) {
    if (isAccountNotFound(error)) return null;
    throw error;
  }
}

export function normalizeAccountSearchQuery(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const query = value.trim();
  return query.length >= MIN_ACCOUNT_SEARCH_QUERY_LENGTH ? query : null;
}

/**
 * Finds a small set of candidate accounts by display name or email so an
 * administrator can confirm the right account before changing its access.
 * Only the minimum fields needed for that decision are returned -- never the
 * full Clerk user record.
 */
export async function searchAccounts(
  query: string,
): Promise<AccountSearchResult[]> {
  const { data } = await clerkClient.users.getUserList({
    query,
    limit: MAX_ACCOUNT_SEARCH_RESULTS,
  });

  return data.map((user) => {
    const profile = fromClerkUser(user);
    const primaryEmail = user.emailAddresses.find(
      (emailAddress) => emailAddress.id === user.primaryEmailAddressId,
    );
    return {
      userId: user.id,
      username: profile.username,
      avatarEmoji: profile.avatarEmoji,
      email: primaryEmail?.emailAddress ?? null,
      banned: isAccountBanned(user.privateMetadata),
    };
  });
}
