/**
 * AI coding assistant route.
 * POST /api/ai/code-assist — streaming Claude response for coding questions.
 * The conversation history is kept client-side; the server is stateless.
 */
import { Router } from "express";
import type { Request, Response } from "express";
import { requireAuthorizedUser } from "../lib/requireAccountAccess";
import { anthropic } from "@workspace/integrations-anthropic-ai";

const router = Router();
const ASSISTANT_REQUEST_COOLDOWN_MS = 1_000;
const ASSISTANT_TIMEOUT_MS = 45_000;
const activeAssistantUsers = new Set<string>();
const lastAssistantRequestAt = new Map<string, number>();

interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

const SYSTEM_PROMPT = `You are DevStudio's AI coding assistant — a senior software engineer who specializes in helping developers debug, design, and ship code.

Guidelines:
- Give clear, concise answers focused on the question asked.
- Always include working code examples when relevant.
- When showing code, use appropriate language syntax highlighting markers.
- If you spot a bug or potential issue in shared code, point it out proactively.
- For architecture questions, consider tradeoffs and explain your reasoning.
- Keep responses focused and actionable — avoid unnecessary preamble.`;

// POST /api/ai/code-assist
router.post(
  "/code-assist",
  async (req: Request, res: Response) => {
    const userId = await requireAuthorizedUser(req, res);
    if (!userId) return;

    const { messages } = req.body as { messages?: unknown };

    if (!Array.isArray(messages) || messages.length === 0) {
      res.status(400).json({ error: "messages array required" });
      return;
    }

    // Validate and sanitize messages
    const chatMessages: ChatMessage[] = [];
    for (const m of messages) {
      if (
        typeof m !== "object" ||
        m === null ||
        !["user", "assistant"].includes(
          (m as Record<string, unknown>).role as string,
        ) ||
        typeof (m as Record<string, unknown>).content !== "string"
      ) {
        res.status(400).json({ error: "Invalid message format" });
        return;
      }
      chatMessages.push({
        role: (m as Record<string, unknown>).role as "user" | "assistant",
        content: ((m as Record<string, unknown>).content as string).slice(
          0,
          16000,
        ),
      });
    }

    // Limit conversation depth to 20 messages to manage tokens
    const trimmed = chatMessages.slice(-20);

    if (activeAssistantUsers.has(userId)) {
      res.setHeader("Retry-After", "1");
      res.status(429).json({ error: "An assistant request is already in progress." });
      return;
    }

    const now = Date.now();
    const lastRequestAt = lastAssistantRequestAt.get(userId) ?? 0;
    const remainingCooldown = ASSISTANT_REQUEST_COOLDOWN_MS - (now - lastRequestAt);
    if (remainingCooldown > 0) {
      res.setHeader("Retry-After", String(Math.ceil(remainingCooldown / 1_000)));
      res.status(429).json({ error: "Please wait before asking again." });
      return;
    }

    activeAssistantUsers.add(userId);
    lastAssistantRequestAt.set(userId, now);

    const controller = new AbortController();
    let clientDisconnected = false;
    const handleResponseClose = () => {
      if (!res.writableEnded) {
        clientDisconnected = true;
        controller.abort();
      }
    };
    res.on("close", handleResponseClose);

    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders();

    const timeout = setTimeout(() => controller.abort(), ASSISTANT_TIMEOUT_MS);
    try {
      const stream = anthropic.messages.stream(
        {
          model: "claude-sonnet-4-6",
          max_tokens: 8192,
          system: SYSTEM_PROMPT,
          messages: trimmed,
        },
        { signal: controller.signal },
      );

      for await (const event of stream) {
        if (clientDisconnected) break;

        if (
          event.type === "content_block_delta" &&
          event.delta.type === "text_delta"
        ) {
          res.write(
            `data: ${JSON.stringify({ content: event.delta.text })}\r\n\r\n`,
          );
        }
      }

      if (!clientDisconnected && !res.destroyed && !res.writableEnded) {
        res.write(`data: ${JSON.stringify({ done: true })}\r\n\r\n`);
        res.end();
      }
    } catch (err) {
      if (!clientDisconnected && !res.destroyed && !res.writableEnded) {
        const message = err instanceof Error ? err.message : "AI service error";
        res.write(`data: ${JSON.stringify({ error: message })}\r\n\r\n`);
        res.end();
      }
    } finally {
      clearTimeout(timeout);
      res.off("close", handleResponseClose);
      activeAssistantUsers.delete(userId);
    }
  },
);

export default router;
