import { HealthCheckResponse, type HealthStatus } from "@workspace/api-zod";
import { Sentry, sentryEnabled } from "./sentry";
import { logger } from "./logger";
import { readPositiveIntEnv } from "./envTuning";
import {
  clearDegradedAlertRecord,
  readDegradedAlertRecord,
  writeDegradedAlertRecord,
  type DegradedAlertRecord,
} from "./healthAlertState";

// Sentry Cron Monitor slug. Sentry expects a check-in at least this often;
// if none arrives (e.g. the process crashed or hung), Sentry marks the
// monitor "missed" and alerts the team via the project's default issue
// alert rule — a "dead man's switch" that catches full outages, not just
// errors reported from within a live process.
const MONITOR_SLUG = "api-server-healthz";
const CHECK_INTERVAL_MINUTES = 5;
const CHECK_INTERVAL_MS = CHECK_INTERVAL_MINUTES * 60 * 1000;
const CHECK_TIMEOUT_MS = 10_000;

/** Readiness payload shape, straight from the shared API contract. */
type HealthReadiness = HealthStatus;

// A configuration fault (a rotated, cleared, or replaced secret) persists
// until someone fixes it, so every one of these checks would report the
// same problem. One alert per cooldown turns a standing fault into a single
// Sentry issue, the same way the Socket.IO rate alerts do, and is
// overridable by environment variable so it can be retuned without a code
// change. The default is far longer than the socket cooldown because this
// check only runs every CHECK_INTERVAL_MINUTES minutes: a cooldown at or
// below that cadence would alert on every check, which is what it exists to
// prevent.
const DEGRADED_ALERT_COOLDOWN_MS = readPositiveIntEnv(
  "HEALTH_DEGRADED_ALERT_COOLDOWN_MS",
  60 * 60_000,
);

let monitorInterval: ReturnType<typeof setInterval> | undefined;
/**
 * The last degraded alert this process knows about. Undefined means the
 * stored record has not been consulted yet, not that no alert was raised —
 * a restart starts here and asks the store on the next degraded check.
 */
let lastDegradedAlert: DegradedAlertRecord | undefined;
/** Whether the previous readable check reported a degraded payload. */
let readinessDegraded = false;
/**
 * Whether a stored alert record may still be standing. True at startup
 * because a previous process may have left one behind, which has to be
 * cleared on the first healthy check or a fault that recovered while the
 * server was down would keep suppressing its own return.
 */
let storedAlertMayExist = true;
/** Recovery was observed but the stored cooldown could not be invalidated. */
let recoveredWithStaleRecord = false;

/**
 * Reads the readiness payload from a healthy HTTP response. Returns
 * undefined when the body cannot be read or does not match the shared
 * contract: the process is clearly alive (it answered 200), so this is a
 * logged warning rather than a failed check-in or a degraded alert built on
 * a payload nobody understood.
 */
async function readReadiness(
  res: Response,
): Promise<HealthReadiness | undefined> {
  let body: unknown;
  try {
    body = await res.json();
  } catch (err) {
    logger.warn({ err }, "Could not read the /api/healthz readiness payload");
    return undefined;
  }

  const parsed = HealthCheckResponse.safeParse(body);
  if (!parsed.success) {
    logger.warn(
      { issues: parsed.error.issues },
      "/api/healthz returned an unrecognized readiness payload",
    );
    return undefined;
  }
  return parsed.data;
}

/** One setting's status, as it reads in an alert: "adminUserIds=missing". */
function describeCheck([name, status]: [string, string]): string {
  return `${name}=${status}`;
}

/**
 * Turns a readiness payload into an alert, a recovery log line, or nothing.
 * This is what catches a configuration problem that starts *after* boot —
 * the startup check runs once, but a secret can be rotated or cleared while
 * the process keeps serving.
 */
async function recordReadiness(readiness: HealthReadiness): Promise<void> {
  if (readiness.status === "ok") {
    if (readinessDegraded) {
      readinessDegraded = false;
      logger.info(
        { checks: readiness.checks },
        "/api/healthz readiness recovered to ok",
      );
    }
    // Re-arm on recovery so a later regression alerts immediately instead
    // of being swallowed by a cooldown the fixed fault started — in the
    // store too, or the next restart would read that cooldown back. Done
    // once per process, including when this server booted healthy and the
    // fault was fixed while it was down. Failed deletes stay pending and
    // cannot be used to suppress a fault that returns in this process.
    lastDegradedAlert = undefined;
    if (storedAlertMayExist) {
      recoveredWithStaleRecord = true;
      if (await clearDegradedAlertRecord()) {
        storedAlertMayExist = false;
        recoveredWithStaleRecord = false;
      }
    }
    return;
  }

  readinessDegraded = true;
  storedAlertMayExist = true;

  // Sorted so the status list reads the same way every time, whatever order
  // the readiness payload happens to use.
  const entries = Object.entries(readiness.checks).sort(([a], [b]) =>
    a.localeCompare(b),
  );
  // Every setting's status, not just the failing ones, is the fault's shape.
  // Matching it against the stored alert is what separates "the same
  // standing fault, already reported" from "something changed": a cleared
  // secret later replaced by a malformed one reads differently here, so it
  // alerts at once rather than hiding behind the first fault's cooldown.
  const fingerprint = entries.map(describeCheck).join(", ");

  const now = Date.now();
  // One store read per process while a fault stands: whichever branch
  // follows leaves `lastDegradedAlert` set for the rest of the cooldown.
  const previous = recoveredWithStaleRecord
    ? undefined
    : (lastDegradedAlert ?? (await readDegradedAlertRecord()));
  if (
    previous &&
    previous.fingerprint === fingerprint &&
    now - previous.alertedAt < DEGRADED_ALERT_COOLDOWN_MS
  ) {
    lastDegradedAlert = previous;
    return;
  }
  lastDegradedAlert = { fingerprint, alertedAt: now };
  recoveredWithStaleRecord = false;

  const failing = entries.filter(([, status]) => status !== "ok");
  const message = `/api/healthz reports degraded readiness: ${
    failing.map(describeCheck).join(", ") || "no failing check reported"
  }`;
  // The log keeps the map: nothing scrubs it, and the recovery and startup
  // lines already carry `checks` in that shape.
  logger.error({ checks: readiness.checks }, message);
  if (sentryEnabled) {
    Sentry.captureMessage(message, {
      level: "error",
      // The whole picture rides in a tag rather than in `extra`. Sentry's
      // server-side scrubber redacts any extra or context string that merely
      // *mentions* a credential — a "clerkSecretKey" key and a
      // "clerkSecretKey=ok" value alike — so the status of the three
      // credential-named settings arrived as "[Filtered]": unreadable for
      // exactly the settings a responder most wants to confirm, and reading
      // as though a value had leaked. Tag values are left alone. Setting
      // name and problem class only; a configured value never reaches here.
      tags: { readinessChecks: entries.map(describeCheck).join(", ") },
    });
  }

  // Written after the alert, never before: the alert is the point, and a
  // store that cannot be written must not be able to hold one back.
  await writeDegradedAlertRecord(lastDegradedAlert);
}

async function pingHealthz(port: number): Promise<void> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), CHECK_TIMEOUT_MS);
  try {
    const res = await fetch(`http://127.0.0.1:${port}/api/healthz`, {
      signal: controller.signal,
    });
    if (!res.ok) {
      throw new Error(`/api/healthz responded with status ${res.status}`);
    }
    // The endpoint stays HTTP 200 while degraded so the startup probe and
    // the uptime monitor keep measuring liveness only, which means the
    // configuration state lives in the body — read it, don't stop at 200.
    const readiness = await readReadiness(res);
    if (readiness) await recordReadiness(readiness);
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Starts a recurring uptime check against this server's own /api/healthz
 * endpoint, reported to Sentry as a Cron Monitor check-in. Requires
 * SENTRY_DSN — without it there is nowhere to send the alert, so the check
 * is skipped entirely rather than silently doing nothing useful.
 */
export function startHealthMonitor(port: number): void {
  stopHealthMonitor();
  lastDegradedAlert = undefined;
  readinessDegraded = false;
  storedAlertMayExist = true;
  recoveredWithStaleRecord = false;

  if (!sentryEnabled) {
    logger.warn("Sentry is disabled; skipping the /api/healthz uptime monitor");
    return;
  }

  const runCheck = (): void => {
    Sentry.withMonitor(MONITOR_SLUG, () => pingHealthz(port), {
      schedule: {
        type: "interval",
        value: CHECK_INTERVAL_MINUTES,
        unit: "minute",
      },
      // How late a check-in may arrive before Sentry considers it missed.
      checkinMargin: 2,
      // How long a single check is allowed to run before being marked failed.
      maxRuntime: 1,
      timezone: "Etc/UTC",
    }).catch((err: unknown) => {
      logger.error({ err }, "/api/healthz uptime check failed");
    });
  };

  runCheck();
  monitorInterval = setInterval(runCheck, CHECK_INTERVAL_MS);
  monitorInterval.unref();
}

/**
 * Stops the recurring uptime check. Safe to call when the monitor is not
 * running or when shutdown is triggered more than once.
 */
export function stopHealthMonitor(): void {
  if (!monitorInterval) return;
  clearInterval(monitorInterval);
  monitorInterval = undefined;
}
