import { db, moderationActionsTable, moderatorsTable } from "@workspace/db";
import { asc, eq } from "drizzle-orm";
import { logger } from "./logger";
import type { ModerationActionRecord } from "./moderationHistory";

export interface GrantedModerator {
  userId: string;
  grantedBy: string;
  grantedAt: Date;
}

/** PostgreSQL "undefined_table". */
const UNDEFINED_TABLE = "42P01";

/** The tables the moderation panel's own endpoints read and write. */
const MODERATION_TABLE = /relation "(moderators|moderation_actions)" does not exist/i;

/**
 * Whether this failure means the moderation tables are not in this
 * database yet.
 *
 * The published database only gains them when the app is published
 * (Replit applies the development-to-production schema diff then), so
 * until that happens the panel has to say so plainly instead of reporting
 * an unexplained server error.
 *
 * Drizzle wraps a driver failure in a DrizzleQueryError whose message is
 * the attempted SQL, and keeps the PostgreSQL error -- the one carrying
 * the code and the relation name -- as its cause, so the check has to walk
 * the cause chain rather than read `code` off the thrown error.
 */
export function isMissingModeratorTable(error: unknown): boolean {
  for (
    let current: unknown = error, depth = 0;
    typeof current === "object" && current !== null && depth < 5;
    depth += 1
  ) {
    const candidate = current as {
      code?: unknown;
      message?: unknown;
      cause?: unknown;
    };
    if (
      candidate.code === UNDEFINED_TABLE &&
      typeof candidate.message === "string" &&
      MODERATION_TABLE.test(candidate.message)
    ) {
      return true;
    }
    current = candidate.cause;
  }
  return false;
}

/**
 * Whether this account appears in the database moderator allow-list.
 *
 * Read on every permission check rather than cached, so a grant or revoke
 * applies to the very next request without a restart or a republish, in
 * development and in production alike.
 *
 * A read failure is logged and reported as "not granted" instead of thrown:
 * permission checks run during ordinary requests (loading a profile,
 * joining a room), and a database problem must not turn those into errors.
 * The ADMIN_USER_IDS bootstrap list is checked separately and keeps working
 * while this table is unreadable, so the moderation tools stay reachable.
 */
export async function isGrantedModerator(userId: string): Promise<boolean> {
  try {
    const [row] = await db
      .select({ userId: moderatorsTable.userId })
      .from(moderatorsTable)
      .where(eq(moderatorsTable.userId, userId))
      .limit(1);
    return row !== undefined;
  } catch (error) {
    logger.error(
      { err: error, userId },
      "failed to read the moderator allow-list",
    );
    return false;
  }
}

/**
 * Every database-granted moderator, oldest grant first.
 *
 * Unlike the permission check above this is only reached from the
 * moderation panel, so a read failure is surfaced to the caller rather than
 * shown as an empty list that would misrepresent who can moderate.
 */
export async function listGrantedModerators(): Promise<GrantedModerator[]> {
  const rows = await db
    .select()
    .from(moderatorsTable)
    .orderBy(asc(moderatorsTable.createdAt));
  return rows.map((row) => ({
    userId: row.userId,
    grantedBy: row.grantedBy,
    grantedAt: row.createdAt,
  }));
}

/**
 * Adds an account to the allow-list and records the grant in moderation
 * history, in one transaction: a privilege change that cannot be audited
 * is rolled back rather than applied silently.
 *
 * Returns false when the account was already granted access, so the caller
 * can report that nothing changed instead of writing a second history
 * entry for an action that had no effect.
 */
export async function grantModerator(
  userId: string,
  grantedBy: string,
  historyRecord: ModerationActionRecord,
): Promise<boolean> {
  return db.transaction(async (tx) => {
    const inserted = await tx
      .insert(moderatorsTable)
      .values({ userId, grantedBy })
      .onConflictDoNothing()
      .returning({ userId: moderatorsTable.userId });
    if (inserted.length === 0) return false;

    await tx.insert(moderationActionsTable).values(historyRecord);
    return true;
  });
}

/**
 * Removes an account from the allow-list and records the revocation, in
 * one transaction for the same reason as granting.
 *
 * Returns false when the account had no granted access, which keeps a
 * mistyped id from being reported as a successful revoke.
 */
export async function revokeModerator(
  userId: string,
  historyRecord: ModerationActionRecord,
): Promise<boolean> {
  return db.transaction(async (tx) => {
    const removed = await tx
      .delete(moderatorsTable)
      .where(eq(moderatorsTable.userId, userId))
      .returning({ userId: moderatorsTable.userId });
    if (removed.length === 0) return false;

    await tx.insert(moderationActionsTable).values(historyRecord);
    return true;
  });
}
