import { Router, type IRouter } from "express";
import adminRouter from "./admin";
import clerkWebhookRouter, { CLERK_WEBHOOK_ROUTE } from "./clerkWebhook";
import healthRouter from "./health";
import aiRouter from "./ai";
import moderationRouter from "./moderation";
import profileRouter from "./profile";
import roomsRouter from "./rooms";

// Single source of truth for where this router is mounted in app.ts. Every
// path that has to agree with the mount - the router itself, the Clerk
// webhook raw-body parser, the advertised URLs - derives from this constant,
// so renaming the prefix cannot leave one of them behind on a stale path.
export const API_MOUNT_PATH = "/api";

const router: IRouter = Router();

router.get("/", (_req, res) => {
  res.status(200).json({
    status: "ready",
    healthCheck: `${API_MOUNT_PATH}/healthz`,
  });
});
router.use(healthRouter);
router.use("/ai", aiRouter);
router.use(CLERK_WEBHOOK_ROUTE, clerkWebhookRouter);
router.use("/admin", adminRouter);
router.use("/profile", profileRouter);
router.use("/rooms", roomsRouter);
router.use("/moderation", moderationRouter);

export default router;
