// Must be imported first, before any other module, so uncaught exceptions and
// unhandled promise rejections thrown during startup are captured too.
import * as Sentry from "@sentry/node";
import { logger } from "./logger";

const dsn = process.env["SENTRY_DSN"];

export const sentryEnabled = Boolean(dsn);

/**
 * Which environment an issue is filed under. Exported so anything that
 * remembers state *about* an alert can key it the same way Sentry separates
 * the alerts themselves — development and production can share one
 * database, and neither should be able to answer for the other.
 */
export const sentryEnvironment = process.env["NODE_ENV"] ?? "development";

if (dsn) {
  Sentry.init({
    dsn,
    environment: sentryEnvironment,
    // Error tracking only — no performance/tracing overhead.
    tracesSampleRate: 0,
  });
  logger.info("Sentry error monitoring initialized");
} else {
  logger.warn(
    "SENTRY_DSN is not set; uncaught errors will not be reported to Sentry",
  );
}

export { Sentry };
