interface User {
  userId: string;
  username: string;
  avatarEmoji: string;
  socketIds: Set<string>;
}

interface Message {
  id: string;
  userId: string;
  username: string;
  avatarEmoji: string;
  timestamp: number;
  type: "text" | "system";
  ciphertext?: string;
  nonce?: string;
  systemContent?: string;
}

interface Room {
  id: string;
  name: string;
  createdByUserId: string;
  users: Map<string, User>;
  messages: Message[];
  sandboxState: { html: string; css: string; js: string };
  createdAt: number;
}

const rooms = new Map<string, Room>();
const DEFAULT_AVATAR_EMOJI = "🧑‍💻";
const DEFAULT_USERNAME = "Member";
const MAX_ASSISTANT_PROMPT_LENGTH = 2_000;
const MAX_ASSISTANT_FILE_LENGTH = 12_000;
const MAX_ASSISTANT_CONTEXT_LENGTH = 24_000;
const ASSISTANT_TIMEOUT_MS = 45_000;
const ASSISTANT_REQUEST_COOLDOWN_MS = 1_000;

type SessionPurpose = "chat" | RoomAccessPurpose;

interface AuthenticatedUser {
  userId: string;
  username: string;
  avatarEmoji: string;
  purpose: SessionPurpose;
  restrictedRoomId?: string;
}

interface SocketData {
  authenticatedUser?: AuthenticatedUser;
  roomId?: string;
}

interface AssistantRequest {
  requestId: string;
  prompt: string;
  files: {
    html: string;
    css: string;
    js: string;
  };
}

interface ActiveAssistantRequest {
  requestId: string;
  controller: AbortController;
  timeout: NodeJS.Timeout;
}

type AppSocket = Socket<
  DefaultEventsMap,
  DefaultEventsMap,
  DefaultEventsMap,
  SocketData
>;
type AppServer = Server<
  DefaultEventsMap,
  DefaultEventsMap,
  DefaultEventsMap,
  SocketData
>;

const KICK_COOLDOWN_MS = 5 * 60 * 1000;
let activeServer: AppServer | null = null;

async function setKickCooldown(roomId: string, userId: string): Promise<void> {
  const expiresAt = new Date(Date.now() + KICK_COOLDOWN_MS);
  await db
    .insert(roomKickCooldownsTable)
    .values({ roomId, userId, expiresAt })
    .onConflictDoUpdate({
      target: [roomKickCooldownsTable.roomId, roomKickCooldownsTable.userId],
      set: { expiresAt },
    });
}

async function hasKickCooldown(
  roomId: string,
  userId: string,
): Promise<boolean> {
  const [cooldown] = await db
    .select({ expiresAt: roomKickCooldownsTable.expiresAt })
    .from(roomKickCooldownsTable)
    .where(
      and(
        eq(roomKickCooldownsTable.roomId, roomId),
        eq(roomKickCooldownsTable.userId, userId),
        gt(roomKickCooldownsTable.expiresAt, new Date()),
      ),
    )
    .limit(1);
  return !!cooldown;
}

async function hasActiveRoomBan(
  roomId: string,
  userId: string,
): Promise<boolean> {
  const [ban] = await db
    .select({ id: roomBansTable.id })
    .from(roomBansTable)
    .where(
      and(
        eq(roomBansTable.roomId, roomId),
        eq(roomBansTable.userId, userId),
        or(
          isNull(roomBansTable.expiresAt),
          gt(roomBansTable.expiresAt, new Date()),
        ),
      ),
    )
    .limit(1);
  return !!ban;
}

function getRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function getRoomId(value: unknown): string | null {
  return typeof value === "string" && /^[a-zA-Z0-9_-]{3,64}$/.test(value)
    ? value
    : null;
}

function getText(value: unknown, maxLength: number): string | null {
  if (typeof value !== "string") return null;
  const text = value.trim();
  return text.length > 0 && text.length <= maxLength ? text : null;
}

function getSandboxFile(value: unknown, maxLength: number): string | null {
  return typeof value === "string" && value.length <= maxLength ? value : null;
}

function getAssistantRequest(value: unknown): AssistantRequest | null {
  const data = getRecord(value);
  const requestId =
    typeof data?.["requestId"] === "string" &&
    /^[a-zA-Z0-9_-]{8,80}$/.test(data["requestId"])
      ? data["requestId"]
      : null;
  const prompt = getText(data?.["prompt"], MAX_ASSISTANT_PROMPT_LENGTH);
  const files = getRecord(data?.["files"]);
  const html = getSandboxFile(files?.["html"], MAX_ASSISTANT_FILE_LENGTH);
  const css = getSandboxFile(files?.["css"], MAX_ASSISTANT_FILE_LENGTH);
  const js = getSandboxFile(files?.["js"], MAX_ASSISTANT_FILE_LENGTH);

  if (
    !requestId ||
    !prompt ||
    html === null ||
    css === null ||
    js === null ||
    html.length + css.length + js.length > MAX_ASSISTANT_CONTEXT_LENGTH
  ) {
    return null;
  }

  return { requestId, prompt, files: { html, css, js } };
}

export function getRooms() {
  return db
    .select({
      id: roomsTable.id,
      name: roomsTable.name,
      createdAt: roomsTable.createdAt,
    })
    .from(roomsTable)
    .where(eq(roomsTable.isActive, true))
    .orderBy(desc(roomsTable.createdAt))
    .then((persistedRooms) => {
      const listedRooms = new Map(
        persistedRooms.map((room) => [
          room.id,
          {
            id: room.id,
            name: room.name,
            userCount: rooms.get(room.id)?.users.size ?? 0,
            createdAt: room.createdAt.getTime(),
          },
        ]),
      );

      for (const room of rooms.values()) {
        if (listedRooms.has(room.id)) continue;
        listedRooms.set(room.id, {
          id: room.id,
          name: room.name,
          userCount: room.users.size,
          createdAt: room.createdAt,
        });
      }

      return [...listedRooms.values()].sort((a, b) => b.createdAt - a.createdAt);
    });
}

function messageFromRow(row: {
  id: string;
  userId: string;
  username: string;
  ciphertext: string | null;
  nonce: string | null;
  type: "text" | "system";
  systemContent: string | null;
  timestampMs: number;
}): Message {
  return {
    id: row.id,
    userId: row.userId,
    username: row.username,
    avatarEmoji: DEFAULT_AVATAR_EMOJI,
    timestamp: row.timestampMs,
    type: row.type,
    ...(row.ciphertext && row.nonce
      ? { ciphertext: row.ciphertext, nonce: row.nonce }
      : {}),
    ...(row.systemContent ? { systemContent: row.systemContent } : {}),
  };
}

async function loadPersistentRoom(roomId: string): Promise<Room | null> {
  const [persistedRoom] = await db
    .select({
      name: roomsTable.name,
      createdBy: roomsTable.createdBy,
      createdAt: roomsTable.createdAt,
      isActive: roomsTable.isActive,
    })
    .from(roomsTable)
    .where(eq(roomsTable.id, roomId))
    .limit(1);
  if (!persistedRoom || !persistedRoom.isActive) return null;

  const persistedMessages = await db
    .select({
      id: messagesTable.id,
      userId: messagesTable.userId,
      username: messagesTable.username,
      ciphertext: messagesTable.ciphertext,
      nonce: messagesTable.nonce,
      type: messagesTable.type,
      systemContent: messagesTable.systemContent,
      timestampMs: messagesTable.timestampMs,
    })
    .from(messagesTable)
    .where(and(eq(messagesTable.roomId, roomId), isNull(messagesTable.deletedAt)))
    .orderBy(asc(messagesTable.timestampMs))
    .limit(200);

  return {
    id: roomId,
    name: persistedRoom.name,
    createdByUserId: persistedRoom.createdBy,
    users: new Map(),
    messages: persistedMessages.map(messageFromRow),
    sandboxState: {
      html: "<h1>Hello, World!</h1>\n<p>Start coding together here.</p>",
      css: "body {\n  font-family: system-ui, sans-serif;\n  padding: 24px;\n  background: #0d0d1a;\n  color: #f1f0ff;\n}\nh1 { color: #6366f1; }",
      js: "// Shared JavaScript sandbox\nconsole.log('Sandbox ready!');\n",
    },
    createdAt: persistedRoom.createdAt.getTime(),
  };
}

async function getRoomKeyEnvelope(roomId: string, userId: string) {
  const [envelope] = await db
    .select({
      ciphertext: roomKeyEnvelopesTable.ciphertext,
      nonce: roomKeyEnvelopesTable.nonce,
      senderPublicKey: roomKeyEnvelopesTable.senderPublicKey,
    })
    .from(roomKeyEnvelopesTable)
    .where(
      and(
        eq(roomKeyEnvelopesTable.roomId, roomId),
        eq(roomKeyEnvelopesTable.userId, userId),
      ),
    )
    .limit(1);
  return envelope ?? null;
}

async function getPublicKey(userId: string): Promise<string | null> {
  const [profile] = await db
    .select({ publicKey: userProfilesTable.publicKey })
    .from(userProfilesTable)
    .where(eq(userProfilesTable.userId, userId))
    .limit(1);
  return profile?.publicKey ?? null;
}

async function recordRoomParticipation(roomId: string, userId: string) {
  await db
    .insert(roomMembersTable)
    .values({ roomId, userId })
    .onConflictDoNothing();
}

async function hasRoomParticipation(roomId: string, userId: string): Promise<boolean> {
  const [member] = await db
    .select({ userId: roomMembersTable.userId })
    .from(roomMembersTable)
    .where(
      and(
        eq(roomMembersTable.roomId, roomId),
        eq(roomMembersTable.userId, userId),
      ),
    )
    .limit(1);
  return !!member;
}

export async function kickRoomMember(
  roomId: string,
  actorId: string,
  targetId: string,
): Promise<
  "ok" | "room-not-found" | "forbidden" | "protected-target" | "target-not-found"
> {
  const io = activeServer;
  const room = rooms.get(roomId);
  if (!io || !room) return "room-not-found";
  if (actorId === targetId) {
    return "forbidden";
  }

  const [persistedRoom] = await db
    .select({ createdBy: roomsTable.createdBy })
    .from(roomsTable)
    .where(eq(roomsTable.id, roomId))
    .limit(1);
  if (!persistedRoom) return "room-not-found";
  if (persistedRoom.createdBy !== actorId && !(await isAdmin(actorId))) {
    return "forbidden";
  }
  if (await isAdmin(targetId)) return "protected-target";

  const target = room.users.get(targetId);
  if (!target) return "target-not-found";

  await setKickCooldown(roomId, targetId);
  for (const socketId of [...target.socketIds]) {
    const targetSocket = io.sockets.sockets.get(socketId) as AppSocket | undefined;
    if (!targetSocket) continue;
    targetSocket.emit("kicked", { roomId, userId: targetId });
    leaveRoom(targetSocket, io, roomId);
  }
  return "ok";
}

export async function closeRoom(
  roomId: string,
  actorId: string,
): Promise<"ok" | "room-not-found" | "forbidden" | "already-closed"> {
  const [roomRecord] = await db
    .select({ id: roomsTable.id, isActive: roomsTable.isActive })
    .from(roomsTable)
    .where(eq(roomsTable.id, roomId))
    .limit(1);
  if (!roomRecord) return "room-not-found";
  if (!roomRecord.isActive) return "already-closed";

  const allowed = (await isAdmin(actorId)) || (await hasRoomParticipation(roomId, actorId));
  if (!allowed) return "forbidden";

  await db
    .update(roomsTable)
    .set({ isActive: false })
    .where(eq(roomsTable.id, roomId));

  const io = activeServer;
  const room = rooms.get(roomId);
  if (io && room) {
    for (const member of room.users.values()) {
      for (const socketId of member.socketIds) {
        const memberSocket = io.sockets.sockets.get(socketId) as AppSocket | undefined;
        if (!memberSocket) continue;
        memberSocket.emit("room-closed", { roomId });
        leaveRoom(memberSocket, io, roomId);
        memberSocket.disconnect(true);
      }
    }
    rooms.delete(roomId);
  }
  return "ok";
}

export async function kickRoomUser(
  roomId: string,
  userId: string,
  banned: boolean,
): Promise<void> {
  const io = activeServer;
  const room = rooms.get(roomId);
  const target = room?.users.get(userId);
  if (!io || !room || !target) return;

  for (const socketId of [...target.socketIds]) {
    const targetSocket = io.sockets.sockets.get(socketId) as AppSocket | undefined;
    if (!targetSocket) continue;
    targetSocket.emit("kicked", { roomId, userId, banned });
    leaveRoom(targetSocket, io, roomId);
  }
}

export function disconnectAccountUser(
  userId: string,
  reason: "banned" | "deleted" = "banned",
): void {
  const io = activeServer;
  if (!io) return;
  for (const socket of io.sockets.sockets.values()) {
    const appSocket = socket as AppSocket;
    if (appSocket.data.authenticatedUser?.userId !== userId) continue;
    appSocket.emit("access-revoked", { reason });
    appSocket.disconnect(true);
  }
}

export function disconnectBannedUser(userId: string): void {
  disconnectAccountUser(userId, "banned");
}

/**
 * Tells one account's own open sessions that its moderator role changed.
 *
 * The role decides which controls the app shows, and the app would otherwise
 * only find out when it next re-reads the profile. Pushing the change down
 * the connection the app already holds means a grant or a revocation reaches
 * it at once, so it can stop asking on a timer.
 *
 * Only the account's own sockets are told; nobody else's copy of the app
 * hears anything. An account with no connection now simply reads the role the
 * next time it asks, so this is a notification and never the record.
 */
export function notifyModeratorAccessChanged(
  userId: string,
  isAdmin: boolean,
): void {
  const io = activeServer;
  if (!io) return;
  for (const socket of io.sockets.sockets.values()) {
    const appSocket = socket as AppSocket;
    if (appSocket.data.authenticatedUser?.userId !== userId) continue;
    appSocket.emit("moderator-access-changed", { isAdmin });
  }
}

export function setupSocketIO(httpServer: HttpServer) {
  const activeAssistantRequests = new Map<string, ActiveAssistantRequest>();
  const lastAssistantRequestAt = new Map<string, number>();
  const io: AppServer = new Server(httpServer, {
    path: "/api/socket.io",
    cors: { methods: ["GET", "POST"] },
    allowRequest(req, callback) {
      callback(null, isAllowedOrigin(req.headers.origin));
    },
  });
  activeServer = io;

  io.use(async (socket: AppSocket, next) => {
    // Wraps the whole handshake, not just the Clerk-token branch: an
    // unexpected failure anywhere here (e.g. getAccountAccess/getAccountProfile
    // hitting a down database) must still resolve `next()` and be reported,
    // rather than leaving the middleware's promise to reject silently.
    try {
      const auth = getRecord(socket.handshake.auth);
      const token = typeof auth?.["token"] === "string" ? auth["token"] : "";
      if (!token) {
        recordSocketAuthFailure("missing_token");
        next(new Error("Authentication required."));
        return;
      }

      const capability = verifyRoomAccessCapability(token);
      if (capability) {
        const access = await getAccountAccess(capability.userId);
        if (!access.allowed) {
          recordSocketAuthFailure(
            access.reason === "banned" ? "banned" : "unverified_email",
          );
          next(
            new Error(
              access.reason === "banned"
                ? "Your DevStudio account has been banned."
                : "Verify your email before entering DevStudio.",
            ),
          );
          return;
        }
        socket.data.authenticatedUser = {
          userId: capability.userId,
          username: capability.username,
          avatarEmoji: capability.avatarEmoji,
          purpose: capability.purpose,
          restrictedRoomId: capability.roomId,
        };
        next();
        return;
      }

      let verifiedToken: Awaited<ReturnType<typeof verifyToken>>;
      try {
        verifiedToken = await verifyToken(token, {
          secretKey: process.env["CLERK_SECRET_KEY"],
        });
      } catch {
        // An invalid, expired, or malformed token is an expected, routine
        // auth rejection (every returning user with a stale session hits
        // this) -- not a bug. Count it for rate monitoring but do not file
        // a Sentry exception per bad handshake.
        recordSocketAuthFailure("invalid_session");
        next(new Error("Invalid session."));
        return;
      }

      const userId = verifiedToken?.sub;
      if (!userId) {
        recordSocketAuthFailure("invalid_session");
        next(new Error("Invalid session."));
        return;
      }
      const access = await getAccountAccess(userId);
      if (!access.allowed) {
        recordSocketAuthFailure(
          access.reason === "banned" ? "banned" : "unverified_email",
        );
        next(
          new Error(
            access.reason === "banned"
              ? "Your DevStudio account has been banned."
              : "Verify your email before entering DevStudio.",
          ),
        );
        return;
      }
      const profile = await getAccountProfile(userId);

      socket.data.authenticatedUser = {
        userId,
        username: profile.username,
        avatarEmoji: profile.avatarEmoji,
        purpose: "chat",
      };
      next();
    } catch (error) {
      // Reaching here means something other than an expected auth
      // rejection broke (capability parsing, getAccountAccess/getAccountProfile
      // throwing, etc.) -- a real bug or infra failure, so it gets a Sentry
      // exception in addition to counting toward the auth-failure rate.
      reportSocketHandlerError("connection-auth", error);
      recordSocketAuthFailure("unexpected_error");
      next(new Error("Invalid session."));
    }
  });

  io.on("connection", (socket: AppSocket) => {
    try {
      setupConnectedSocket(socket, io, activeAssistantRequests, lastAssistantRequestAt);
    } catch (error) {
      reportSocketHandlerError("connection", error, { sid: socket.id });
      socket.disconnect(true);
    }
  });

  return io;
}

function setupConnectedSocket(
  socket: AppSocket,
  io: AppServer,
  activeAssistantRequests: Map<string, ActiveAssistantRequest>,
  lastAssistantRequestAt: Map<string, number>,
): void {
  const authenticatedUser = socket.data.authenticatedUser;
  if (!authenticatedUser) {
    socket.disconnect(true);
    return;
  }
  logger.info({ sid: socket.id, userId: authenticatedUser.userId }, "socket connected");

  const finishAssistantRequest = (requestId: string, cancelled = false) => {
    const active = activeAssistantRequests.get(socket.id);
    if (!active || active.requestId !== requestId) return;
    clearTimeout(active.timeout);
    activeAssistantRequests.delete(socket.id);
    socket.emit("assistant-done", { requestId, cancelled });
  };

  const abortAssistantRequest = (notifyClient = false) => {
    const active = activeAssistantRequests.get(socket.id);
    if (!active) return;
    active.controller.abort();
    clearTimeout(active.timeout);
    activeAssistantRequests.delete(socket.id);
    if (notifyClient) {
      socket.emit("assistant-done", {
        requestId: active.requestId,
        cancelled: true,
      });
    }
  };

  socket.on("join-room", async (payload: unknown) => {
    try {
      const data = getRecord(payload);
      const roomId = getRoomId(data?.["roomId"]);
      if (!roomId) {
        socket.emit("error", { message: "Invalid room." });
        return;
      }
      if (
        authenticatedUser.restrictedRoomId &&
        authenticatedUser.restrictedRoomId !== roomId
      ) {
        socket.emit("error", { message: "This room access session is restricted." });
        return;
      }

      if (await hasActiveRoomBan(roomId, authenticatedUser.userId)) {
        socket.emit("error", {
          code: "ROOM_BANNED",
          message: "You are banned from this room",
        });
        return;
      }

      if (await hasKickCooldown(roomId, authenticatedUser.userId)) {
        socket.emit("error", {
          message:
            "You were recently removed from this room. Please wait a few minutes before rejoining.",
        });
        return;
      }

      const currentRoomId = socket.data.roomId;
      if (currentRoomId && currentRoomId !== roomId) {
        leaveRoom(socket, io, currentRoomId);
      }

      if (!rooms.has(roomId)) {
        const requestedName = getText(data?.["roomName"], 60) ?? roomId;
        if (data?.["createIfMissing"] !== false) {
          await db
            .insert(roomsTable)
            .values({
              id: roomId,
              name: requestedName,
              createdBy: authenticatedUser.userId,
            })
            .onConflictDoNothing();
        }
        const persistedRoom = await loadPersistentRoom(roomId);
        if (!persistedRoom) {
          const closedRoomRows = await db
            .select({ isActive: roomsTable.isActive })
            .from(roomsTable)
            .where(eq(roomsTable.id, roomId))
            .limit(1);
          const closedRoom = closedRoomRows?.[0];
          if (closedRoom && !closedRoom.isActive) {
            socket.emit("error", {
              code: "ROOM_CLOSED",
              message: "This room has been permanently closed.",
            });
            return;
          }
          socket.emit("error", { message: "Room not found." });
          return;
        }
        rooms.set(roomId, persistedRoom);
      }

      const room = rooms.get(roomId);
      if (!room) return;
      const existingEnvelope = await getRoomKeyEnvelope(
        roomId,
        authenticatedUser.userId,
      );
      const anyEnvelopeRows = await db
        .select({ userId: roomKeyEnvelopesTable.userId })
        .from(roomKeyEnvelopesTable)
        .where(eq(roomKeyEnvelopesTable.roomId, roomId))
        .limit(1);
      const anyEnvelope = anyEnvelopeRows?.[0];
      const canInitializeKey = !anyEnvelope;
      await recordRoomParticipation(roomId, authenticatedUser.userId);
      const existingUser = room.users.get(authenticatedUser.userId);
      const isNewPresence = !existingUser;
      const user =
        existingUser ?? {
          userId: authenticatedUser.userId,
          username: authenticatedUser.username,
          avatarEmoji: authenticatedUser.avatarEmoji,
          socketIds: new Set<string>(),
        };
      user.username = authenticatedUser.username;
      user.avatarEmoji = authenticatedUser.avatarEmoji;
      user.socketIds.add(socket.id);
      room.users.set(user.userId, user);
      socket.join(roomId);
      socket.data.roomId = roomId;

      socket.emit("room-joined", {
        roomId,
        roomName: room.name,
        messages: room.messages.slice(-80),
        users: Array.from(room.users.values()).map((member) => ({
          userId: member.userId,
          username: member.username,
          avatarEmoji: member.avatarEmoji,
        })),
        // Room moderation is granted to the room's creator and to accounts
        // holding the moderator role. Only ownership is reported here: it
        // cannot change while the room is open, whereas the role can be
        // granted or removed at any moment, so the client reads that live
        // from its own account profile instead of from this answer.
        isRoomCreator: room.createdByUserId === user.userId,
        canClose: true,
        canInitializeKey,
        roomKeyEnvelope: existingEnvelope ?? undefined,
        sandboxState: room.sandboxState,
      });

      if (isNewPresence) {
        const sysMsg = makeSystemMsg(`${user.username} joined`);
        room.messages.push(sysMsg);
        void persistSystemMessage(roomId, sysMsg);
        socket.to(roomId).emit("user-joined", {
          userId: user.userId,
          username: user.username,
          avatarEmoji: user.avatarEmoji,
          message: sysMsg,
        });
      }
      if (!existingEnvelope && !canInitializeKey) {
        const publicKey = await getPublicKey(user.userId);
        if (publicKey) {
          for (const member of room.users.values()) {
            if (member.userId === user.userId) continue;
            for (const memberSocketId of member.socketIds) {
              io.to(memberSocketId).emit("room-key-needed", {
                roomId,
                userId: user.userId,
                publicKey,
              });
            }
          }
        }
      }
      logger.info({ roomId, userId: user.userId }, "user joined room");
    } catch (error) {
      reportSocketHandlerError("join-room", error, {
        sid: socket.id,
        userId: authenticatedUser.userId,
      });
      socket.emit("error", { message: "Unable to join this room. Please try again." });
    }
  });

  socket.on("assistant-request", (payload: unknown) => {
      if (authenticatedUser.purpose !== "sandbox") {
        socket.emit("assistant-error", {
          message: "This session cannot use the coding assistant.",
        });
        return;
      }

      const request = getAssistantRequest(payload);
      const requestedRoomId = getRoomId(getRecord(payload)?.["roomId"]);
      const room =
        requestedRoomId === authenticatedUser.restrictedRoomId
          ? getJoinedRoom(socket, requestedRoomId)
          : null;
      if (!request || !room) {
        socket.emit("assistant-error", {
          requestId: request?.requestId,
          message: "Join the sandbox room with a short question and valid files.",
        });
        return;
      }

      if (activeAssistantRequests.has(socket.id)) {
        socket.emit("assistant-error", {
          requestId: request.requestId,
          message: "Wait for the current response or cancel it first.",
        });
        return;
      }

      const now = Date.now();
      const lastRequest = lastAssistantRequestAt.get(authenticatedUser.userId) ?? 0;
      if (now - lastRequest < ASSISTANT_REQUEST_COOLDOWN_MS) {
        socket.emit("assistant-error", {
          requestId: request.requestId,
          message: "Please wait a moment before asking again.",
        });
        return;
      }
      lastAssistantRequestAt.set(authenticatedUser.userId, now);

      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), ASSISTANT_TIMEOUT_MS);
      activeAssistantRequests.set(socket.id, {
        requestId: request.requestId,
        controller,
        timeout,
      });

      void streamSandboxAssistant({
        prompt: request.prompt,
        files: request.files,
        signal: controller.signal,
        onText(text) {
          const active = activeAssistantRequests.get(socket.id);
          if (active?.requestId === request.requestId && !controller.signal.aborted) {
            socket.emit("assistant-chunk", { requestId: request.requestId, text });
          }
        },
      })
        .then(() => finishAssistantRequest(request.requestId))
        .catch((error: unknown) => {
          const active = activeAssistantRequests.get(socket.id);
          if (active?.requestId !== request.requestId) return;
          if (controller.signal.aborted) {
            finishAssistantRequest(request.requestId, true);
            return;
          }
          clearTimeout(active.timeout);
          activeAssistantRequests.delete(socket.id);
          const rateLimited = isAnthropicRateLimitError(error);
          const retryAfter = getAnthropicRetryAfterSeconds(error);
          socket.emit("assistant-error", {
            requestId: request.requestId,
            message: rateLimited
              ? "The coding assistant is rate-limited right now. Please wait and try again."
              : "The coding assistant is unavailable. Please try again.",
            ...(rateLimited ? { errorCategory: "rate_limit" } : {}),
            ...(retryAfter !== undefined ? { retryAfter } : {}),
          });
        });
    });

    socket.on("assistant-cancel", (payload: unknown) => {
      const data = getRecord(payload);
      const requestId = data?.["requestId"];
      const roomId = getRoomId(data?.["roomId"]);
      const active = activeAssistantRequests.get(socket.id);
      if (
        authenticatedUser.purpose !== "sandbox" ||
        typeof requestId !== "string" ||
        roomId !== socket.data.roomId ||
        active?.requestId !== requestId
      ) {
        return;
      }
      abortAssistantRequest(true);
    });

    socket.on("room-key-share", async (payload: unknown) => {
      try {
        if (authenticatedUser.purpose !== "chat") return;
        const data = getRecord(payload);
        const roomId = getRoomId(data?.["roomId"]);
        const targetUserId = getText(data?.["userId"], 128);
        const ciphertext = getText(data?.["ciphertext"], 20_000);
        const nonce = getText(data?.["nonce"], 200);
        const senderPublicKey = getText(data?.["senderPublicKey"], 200);
        const room = roomId ? getJoinedRoom(socket, roomId) : null;
        if (!room || !targetUserId || !ciphertext || !nonce || !senderPublicKey) return;
        if (!roomId || !(await hasRoomParticipation(roomId, targetUserId))) return;
        const expectedSenderKey = await getPublicKey(authenticatedUser.userId);
        if (!expectedSenderKey || expectedSenderKey !== senderPublicKey) return;

        await db
          .insert(roomKeyEnvelopesTable)
          .values({
            roomId,
            userId: targetUserId,
            ciphertext,
            nonce,
            senderPublicKey,
          })
          .onConflictDoUpdate({
            target: [roomKeyEnvelopesTable.roomId, roomKeyEnvelopesTable.userId],
            set: { ciphertext, nonce, senderPublicKey },
          });

        const target = room.users.get(targetUserId);
        if (!target) return;
        for (const targetSocketId of target.socketIds) {
          io.to(targetSocketId).emit("room-key-envelope", {
            roomId,
            ciphertext,
            nonce,
            senderPublicKey,
          });
        }
      } catch (error) {
        reportSocketHandlerError("room-key-share", error, {
          sid: socket.id,
          userId: authenticatedUser.userId,
        });
      }
    });

    socket.on("message", async (payload: unknown) => {
      if (authenticatedUser.purpose !== "chat") return;
      const data = getRecord(payload);
      const roomId = getRoomId(data?.["roomId"]);
      const ciphertext = getText(data?.["ciphertext"], 20_000);
      const nonce = getText(data?.["nonce"], 200);
      const room = roomId ? getJoinedRoom(socket, roomId) : null;
      if (!room || nonce === null || !isEncryptedMessagePayload(ciphertext, nonce)) return;
      const msg: Message = {
        id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
        userId: authenticatedUser.userId,
        username: authenticatedUser.username,
        avatarEmoji: authenticatedUser.avatarEmoji,
        timestamp: Date.now(),
        type: "text",
        ciphertext,
        nonce,
      };
      room.messages.push(msg);
      if (room.messages.length > 200) room.messages = room.messages.slice(-200);
      await db.insert(messagesTable).values({
        id: msg.id,
        roomId: room.id,
        userId: msg.userId,
        username: msg.username,
        ciphertext,
        nonce,
        type: "text",
        timestampMs: msg.timestamp,
      });
      io.to(room.id).emit("message", msg);
    });

    socket.on("sandbox-update", (payload: unknown) => {
      if (authenticatedUser.purpose !== "sandbox") return;
      const data = getRecord(payload);
      const roomId = getRoomId(data?.["roomId"]);
      const html = getText(data?.["html"], 100_000);
      const css = getText(data?.["css"], 100_000);
      const js = getText(data?.["js"], 100_000);
      const room = roomId ? getJoinedRoom(socket, roomId) : null;
      if (!room || html === null || css === null || js === null) return;
      room.sandboxState = { html, css, js };
      socket.to(room.id).emit("sandbox-update", { html, css, js });
    });

    socket.on("webrtc-offer", (payload: unknown) => {
      relayWebRtc(socket, io, "webrtc-offer", "offer", payload);
    });
    socket.on("webrtc-answer", (payload: unknown) => {
      relayWebRtc(socket, io, "webrtc-answer", "answer", payload);
    });
    socket.on("webrtc-ice", (payload: unknown) => {
      relayWebRtc(socket, io, "webrtc-ice", "candidate", payload);
    });

    socket.on("leave-room", (payload: unknown) => {
      const data = getRecord(payload);
      const roomId = getRoomId(data?.["roomId"]);
      if (roomId) {
        abortAssistantRequest();
        leaveRoom(socket, io, roomId);
      }
    });

    socket.on("close-room", async (payload: unknown) => {
      const roomId = getRoomId(getRecord(payload)?.["roomId"]);
      if (!roomId || roomId !== socket.data.roomId) return;
      const result = await closeRoom(roomId, authenticatedUser.userId);
      if (result === "forbidden") {
        socket.emit("error", { code: "ROOM_CLOSE_FORBIDDEN", message: "You cannot close this room." });
      } else if (result === "room-not-found") {
        socket.emit("error", { code: "ROOM_NOT_FOUND", message: "Room not found." });
      }
    });

  socket.on("disconnect", (reason: string) => {
    recordSocketDisconnect(reason);
    abortAssistantRequest();
    if (socket.data.roomId) leaveRoom(socket, io, socket.data.roomId);
    logger.info({ sid: socket.id, reason }, "socket disconnected");
  });
}

function getJoinedRoom(socket: AppSocket, roomId: string): Room | null {
  const userId = socket.data.authenticatedUser?.userId;
  const room = rooms.get(roomId);
  if (
    !userId ||
    !room ||
    socket.data.roomId !== roomId ||
    !socket.rooms.has(roomId) ||
    !room.users.get(userId)?.socketIds.has(socket.id)
  ) {
    return null;
  }
  return room;
}

function leaveRoom(socket: AppSocket, io: AppServer, roomId: string) {
  const room = rooms.get(roomId);
  const userId = socket.data.authenticatedUser?.userId;
  if (!room || !userId) return;
  const user = room.users.get(userId);
  if (!user) return;
  user.socketIds.delete(socket.id);
  socket.leave(roomId);
  if (socket.data.roomId === roomId) socket.data.roomId = undefined;
  if (user.socketIds.size > 0) return;
  room.users.delete(userId);
  const sysMsg = makeSystemMsg(`${user.username} left`);
  room.messages.push(sysMsg);
  void persistSystemMessage(roomId, sysMsg);
  if (room.users.size === 0) return;
  io.to(roomId).emit("user-left", { userId, username: user.username, message: sysMsg });
}

function relayWebRtc(
  socket: AppSocket,
  io: AppServer,
  event: "webrtc-offer" | "webrtc-answer" | "webrtc-ice",
  field: "offer" | "answer" | "candidate",
  payload: unknown,
) {
  const authenticatedUser = socket.data.authenticatedUser;
  if (!authenticatedUser || authenticatedUser.purpose !== "call") return;
  const data = getRecord(payload);
  const roomId = getRoomId(data?.["roomId"]);
  const targetUserId = getText(data?.["to"], 128);
  const room = roomId ? getJoinedRoom(socket, roomId) : null;
  if (!room || !targetUserId || data?.[field] === undefined) return;

  const targetUser = room.users.get(targetUserId);
  if (!targetUser) return;
  for (const targetSocketId of targetUser.socketIds) {
    io.to(targetSocketId).emit(event, {
      roomId,
      from: authenticatedUser.userId,
      [field]: data[field],
    });
  }
}

function makeSystemMsg(content: string): Message {
  return {
    id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    userId: "system", username: "System",
    avatarEmoji: DEFAULT_AVATAR_EMOJI,
    timestamp: Date.now(), type: "system",
    systemContent: content,
  };
}

async function persistSystemMessage(roomId: string, message: Message): Promise<void> {
  await db.insert(messagesTable).values({
    id: message.id,
    roomId,
    userId: message.userId,
    username: message.username,
    type: "system",
    systemContent: message.systemContent ?? "",
    timestampMs: message.timestamp,
  });
}
