import { Router, type IRouter } from "express";
import { HealthCheckResponse } from "@workspace/api-zod";
import { inspectServerConfiguration } from "../lib/serverConfig";

const router: IRouter = Router();

router.get("/healthz", (_req, res) => {
  // Problem class per setting only — the startup log carries the shape
  // detail, and nothing anywhere carries a configured value.
  const checks = inspectServerConfiguration();
  const data = HealthCheckResponse.parse({
    // Still HTTP 200 while degraded: the process is alive and serving, which
    // is what the deployment startup probe and the Sentry uptime monitor
    // measure. The body carries the configuration problem so a reader sees it
    // without an outage being declared over one broken feature.
    status: Object.values(checks).every((status) => status === "ok")
      ? "ok"
      : "degraded",
    checks,
  });
  res.json(data);
});

export default router;
