import { Sentry } from "./sentry";
import { logger } from "./logger";
import {
  inspectClerkWebhookSigningSecret,
  reportClerkWebhookSigningSecretStatus,
} from "./clerkWebhookSecret";

/**
 * Startup checks for the settings the server cannot work without.
 *
 * Same approach as the Clerk webhook signing secret check: read each value
 * once at boot, describe its shape problem without ever repeating the value,
 * and report the outcome in two places — one loud startup signal (error log
 * plus a Sentry issue) and a standing entry in /api/healthz, because the
 * startup log scrolls away and the readiness payload does not.
 *
 * Only a setting the API cannot serve *anything* without stops startup. The
 * rest degrade readiness so one broken feature does not take the whole
 * process down.
 */

export type ConfigCheckStatus = "ok" | "missing" | "malformed";
export type ConfigProblemStatus = Exclude<ConfigCheckStatus, "ok">;

export type ServerConfigCheckName =
  | "clerkWebhookSigningSecret"
  | "databaseUrl"
  | "clerkSecretKey"
  | "clerkPublishableKey"
  | "sessionSecret"
  | "adminUserIds";

export type ServerConfigurationChecks = Record<
  ServerConfigCheckName,
  ConfigCheckStatus
>;

interface ConfigCheckDefinition {
  /** Environment variable that carries the value. */
  envVar: string;
  /** What stops working while the value is unusable. */
  impact: string;
  /** Plain description of an acceptable value. Never a real value. */
  expectation: string;
  /** Problem classes that stop startup instead of degrading readiness. */
  fatalStatuses: readonly ConfigProblemStatus[];
  /**
   * Describes why the configured value cannot work, or null when it can.
   * Descriptions cover shape only — prefix, length, entry count — so a
   * secret can never reach a log, a Sentry issue, or the health payload.
   */
  findShapeProblem: (value: string) => string | null;
}

const MIN_SESSION_SECRET_LENGTH = 16;
const CLERK_SECRET_KEY_PREFIXES = ["sk_test_", "sk_live_"] as const;
const CLERK_PUBLISHABLE_KEY_PREFIXES = ["pk_test_", "pk_live_"] as const;
const CLERK_USER_ID_PATTERN = /^user_[A-Za-z0-9]+$/;

function findWhitespaceProblem(value: string): string | null {
  return value.trim() === value ? null : "has leading or trailing whitespace";
}

function quoteList(values: readonly string[]): string {
  return values.map((value) => `"${value}"`).join(" or ");
}

function findClerkKeyProblem(
  value: string,
  prefixes: readonly string[],
  mixUpPrefix: string,
  mixUpName: string,
): string | null {
  const whitespace = findWhitespaceProblem(value);
  if (whitespace) return whitespace;

  const prefix = prefixes.find((candidate) => value.startsWith(candidate));
  if (!prefix) {
    const mixUp = value.startsWith(mixUpPrefix)
      ? ` (it looks like the ${mixUpName}, a common mix-up)`
      : "";
    return `is ${value.length} characters with no ${quoteList(prefixes)} prefix${mixUp}`;
  }
  if (value.length === prefix.length) {
    return `is only the "${prefix}" prefix with no key body`;
  }

  return null;
}

/**
 * pg accepts both URI and "host=... dbname=..." keyword connection strings.
 * Only URI-shaped values are inspected: a keyword string this check cannot
 * fully validate is left alone rather than wrongly reported as broken.
 */
function findDatabaseUrlProblem(value: string): string | null {
  const whitespace = findWhitespaceProblem(value);
  if (whitespace) return whitespace;

  if (!/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(value)) {
    return value.includes("=")
      ? null
      : "is neither a postgres:// URL nor a key=value connection string";
  }

  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return "is not a parseable URL";
  }

  if (url.protocol !== "postgres:" && url.protocol !== "postgresql:") {
    return `uses the "${url.protocol}//" scheme, expected "postgres://" or "postgresql://"`;
  }
  if (!url.hostname) {
    return "has no host";
  }

  return null;
}

function findSessionSecretProblem(value: string): string | null {
  const whitespace = findWhitespaceProblem(value);
  if (whitespace) return whitespace;

  if (value.length < MIN_SESSION_SECRET_LENGTH) {
    return `is ${value.length} characters, expected at least ${MIN_SESSION_SECRET_LENGTH}`;
  }

  return null;
}

function findAdminUserIdsProblem(value: string): string | null {
  const entries = value.split(",").map((entry) => entry.trim());

  const empty = entries.filter((entry) => entry === "").length;
  if (empty > 0) {
    return `has ${empty} empty ${empty === 1 ? "entry" : "entries"} (a stray or doubled comma)`;
  }

  const invalid = entries.filter(
    (entry) => !CLERK_USER_ID_PATTERN.test(entry),
  ).length;
  if (invalid > 0) {
    return `has ${invalid} of ${entries.length} entries that are not Clerk user ids`;
  }

  return null;
}

const CONFIG_CHECKS = {
  databaseUrl: {
    envVar: "DATABASE_URL",
    impact:
      "Every route and Socket.IO handler that reads or writes stored data will fail.",
    expectation: 'Expected a "postgres://" connection string.',
    // The one genuinely fatal setting: every route and Socket.IO handler
    // reads or writes stored data. A malformed value only degrades, because
    // the shape check above deliberately cannot validate every form pg
    // accepts, and a false positive must never take the server down.
    fatalStatuses: ["missing"],
    findShapeProblem: findDatabaseUrlProblem,
  },
  clerkSecretKey: {
    envVar: "CLERK_SECRET_KEY",
    impact:
      "Every authenticated request and Socket.IO handshake will be rejected.",
    expectation: `Expected ${quoteList(CLERK_SECRET_KEY_PREFIXES)} followed by the key body.`,
    fatalStatuses: [],
    findShapeProblem: (value) =>
      findClerkKeyProblem(
        value,
        CLERK_SECRET_KEY_PREFIXES,
        "pk_",
        "publishable key",
      ),
  },
  clerkPublishableKey: {
    envVar: "CLERK_PUBLISHABLE_KEY",
    impact:
      "Clerk cannot complete session handshakes, so sign-in can fail even with a usable secret key.",
    expectation: `Expected ${quoteList(CLERK_PUBLISHABLE_KEY_PREFIXES)} followed by the key body.`,
    fatalStatuses: [],
    findShapeProblem: (value) =>
      findClerkKeyProblem(
        value,
        CLERK_PUBLISHABLE_KEY_PREFIXES,
        "sk_",
        "secret key",
      ),
  },
  sessionSecret: {
    envVar: "SESSION_SECRET",
    impact:
      "Room access capabilities cannot be signed or verified, so calls and the shared sandbox will not start.",
    expectation: `Expected at least ${MIN_SESSION_SECRET_LENGTH} characters of random text.`,
    fatalStatuses: [],
    findShapeProblem: findSessionSecretProblem,
  },
  adminUserIds: {
    envVar: "ADMIN_USER_IDS",
    impact: "No account can reach the moderation tools.",
    expectation:
      'Expected a comma-separated list of Clerk user ids ("user_" followed by letters and digits).',
    fatalStatuses: [],
    findShapeProblem: findAdminUserIdsProblem,
  },
} satisfies Record<
  Exclude<ServerConfigCheckName, "clerkWebhookSigningSecret">,
  ConfigCheckDefinition
>;

interface ConfigCheckResult {
  status: ConfigCheckStatus;
  detail: string | null;
}

/**
 * Reads one setting at call time — never at import time — so a test or a
 * later configuration change is reflected by the next /api/healthz response
 * instead of a value frozen at boot.
 */
function inspectCheck(definition: ConfigCheckDefinition): ConfigCheckResult {
  const value = process.env[definition.envVar];

  if (value === undefined) {
    return { status: "missing", detail: "is not set" };
  }
  if (value.trim() === "") {
    return { status: "missing", detail: "is set to an empty value" };
  }

  const problem = definition.findShapeProblem(value);
  if (problem) {
    return { status: "malformed", detail: problem };
  }

  return { status: "ok", detail: null };
}

/**
 * Current status of every configuration check, as reported by /api/healthz.
 * Problem class only — the shape detail stays in the server log.
 */
export function inspectServerConfiguration(): ServerConfigurationChecks {
  return {
    clerkWebhookSigningSecret: inspectClerkWebhookSigningSecret().status,
    databaseUrl: inspectCheck(CONFIG_CHECKS.databaseUrl).status,
    clerkSecretKey: inspectCheck(CONFIG_CHECKS.clerkSecretKey).status,
    clerkPublishableKey: inspectCheck(CONFIG_CHECKS.clerkPublishableKey).status,
    sessionSecret: inspectCheck(CONFIG_CHECKS.sessionSecret).status,
    adminUserIds: inspectCheck(CONFIG_CHECKS.adminUserIds).status,
  };
}

/**
 * Startup check: turns missing or unusable settings into one loud signal per
 * problem instead of a failing request whenever a feature first needs the
 * value. Every problem is reported before a fatal one stops the process, so
 * a boot log shows the full picture rather than the first fault only.
 *
 * Throws when a setting the API cannot serve without is unusable.
 */
export function reportServerConfigurationStatus(): void {
  reportClerkWebhookSigningSecretStatus();

  const fatalEnvVars: string[] = [];

  for (const [name, definition] of Object.entries(CONFIG_CHECKS) as [
    ServerConfigCheckName,
    ConfigCheckDefinition,
  ][]) {
    const { status, detail } = inspectCheck(definition);
    if (status === "ok") continue;

    const fatal = definition.fatalStatuses.includes(status);
    const message =
      `${definition.envVar} ${detail}. ${definition.impact}` +
      `${fatal ? " Startup cannot continue." : ""} ${definition.expectation}`;
    logger.error(
      { envVar: definition.envVar, check: name, configStatus: status, detail },
      message,
    );
    Sentry.captureMessage(message, "error");

    if (fatal) {
      fatalEnvVars.push(definition.envVar);
    }
  }

  logger.info(
    { checks: inspectServerConfiguration() },
    "Server configuration checked",
  );

  if (fatalEnvVars.length > 0) {
    throw new Error(
      `Server configuration is unusable: ${fatalEnvVars.join(", ")}. See the errors logged above.`,
    );
  }
}
