import { Router, type Request, type Response } from "express";
import { getAccountProfile } from "../lib/accountProfile";
import { createRoomAccessCapability, type RoomAccessPurpose } from "../lib/roomAccess";
import { requireAuthorizedUser } from "../lib/requireAccountAccess";
import { buildCallHtml, buildSandboxHtmlWithAssistant } from "./roomDocuments";
import { closeRoom, getRooms } from "../socket";
import { db, roomMembersTable, roomsTable } from "@workspace/db";
import { and, eq } from "drizzle-orm";
import { isAdmin } from "../lib/accountAccess";

const router = Router();
const DEFAULT_AVATAR_EMOJI = "🧑‍💻";

router.get("/", async (req, res) => {
  if (!(await requireAuthorizedUser(req, res))) return;
  res.setHeader("Cache-Control", "no-store");
  res.json({ rooms: await getRooms() });
});

router.post("/:roomId/close", async (req, res) => {
  const userId = await requireAuthorizedUser(req, res);
  if (!userId) return;
  const roomId = req.params["roomId"];
  if (typeof roomId !== "string" || !/^[a-zA-Z0-9_-]{3,64}$/.test(roomId)) {
    res.status(400).json({ error: "A valid room is required." });
    return;
  }
  const [room] = await db
    .select({ id: roomsTable.id, isActive: roomsTable.isActive })
    .from(roomsTable)
    .where(eq(roomsTable.id, roomId))
    .limit(1);
  if (!room) {
    res.status(404).json({ error: "Room not found." });
    return;
  }
  const [membership] = await db
    .select({ userId: roomMembersTable.userId })
    .from(roomMembersTable)
    .where(
      and(
        eq(roomMembersTable.roomId, roomId),
        eq(roomMembersTable.userId, userId),
      ),
    )
    .limit(1);
  if (!membership && !(await isAdmin(userId))) {
    res.status(403).json({ error: "Room participant or administrator permission required." });
    return;
  }
  const result = await closeRoom(roomId, userId);
  if (result === "already-closed") {
    res.status(409).json({ error: "Room is already closed." });
    return;
  }
  if (result !== "ok") {
    res.status(result === "room-not-found" ? 404 : 403).json({ error: "Unable to close room." });
    return;
  }
  res.json({ ok: true });
});

router.get("/call", (req, res) => {
  void renderRoomDocument(req, res, "call");
});

router.get("/sandbox", (req, res) => {
  void renderRoomDocument(req, res, "sandbox");
});

async function renderRoomDocument(
  req: Request,
  res: Response,
  purpose: RoomAccessPurpose,
) {
  const userId = await requireAuthorizedUser(req, res);
  if (!userId) return;
  const roomId = getRoomId(req.query["roomId"]);
  if (!roomId) {
    res.status(400).json({ error: "A valid room is required." });
    return;
  }

  let profile;
  try {
    profile = await getAccountProfile(userId);
  } catch {
    res.status(503).json({ error: "Account profile is temporarily unavailable." });
    return;
  }
  const capability = createRoomAccessCapability({
    roomId,
    userId,
    username: profile.username,
    avatarEmoji: profile.avatarEmoji,
    purpose,
  });

  res
    .setHeader("Content-Type", "text/html; charset=utf-8")
    .setHeader("Cache-Control", "no-store")
    .setHeader("Referrer-Policy", "no-referrer")
    .send(
      purpose === "call"
        ? buildCallHtml({ roomId, userId, username: profile.username, capability })
        : buildSandboxHtmlWithAssistant({
            roomId,
            username: profile.username,
            capability,
          }),
    );
}

function getRoomId(value: unknown): string | null {
  const roomId = typeof value === "string" ? value : "";
  return /^[a-zA-Z0-9_-]{3,64}$/.test(roomId) ? roomId : null;
}

export default router;
