import { getAuth } from "@clerk/express";
import { Router } from "express";
import {
  getAccountProfile,
  normalizeProfileAvatar,
  normalizeProfileUsername,
  syncUserPublicKey,
  updateAccountProfile,
} from "../lib/accountProfile";
import { isAdmin } from "../lib/accountAccess";
import { isProfileAvatar } from "../lib/profileAvatars";
import { requireAuthorizedUser } from "../lib/requireAccountAccess";
import { deleteAccount } from "../lib/accountDeletion";
import { disconnectAccountUser } from "../socket";

const router = Router();

router.get("/", async (req, res, next) => {
  const userId = await requireAuthorizedUser(req, res);
  if (!userId) return;
  try {
    res.json({
      profile: await getAccountProfile(userId),
      isAdmin: await isAdmin(userId),
    });
  } catch (error) {
    next(error);
  }
});

router.put("/", async (req, res, next) => {
  const userId = await requireAuthorizedUser(req, res);
  if (!userId) return;
  const body =
    req.body !== null && typeof req.body === "object" && !Array.isArray(req.body)
      ? (req.body as Record<string, unknown>)
      : null;
  const username = body?.["username"];
  const avatarEmoji = body?.["avatarEmoji"];
  const publicKey = body?.["publicKey"];
  if (
    (username !== undefined &&
      (typeof username !== "string" ||
        username.trim().replace(/\s+/g, " ").length < 2 ||
        username.trim().replace(/\s+/g, " ").length > 30)) ||
    (avatarEmoji !== undefined && !isProfileAvatar(avatarEmoji)) ||
    (publicKey !== undefined &&
      (typeof publicKey !== "string" ||
        !/^[A-Za-z0-9+/]{40,100}={0,2}$/.test(publicKey)))
  ) {
    res.status(400).json({ error: "Invalid profile details." });
    return;
  }

  try {
    const current = await getAccountProfile(userId);
    if (publicKey !== undefined) {
      await syncUserPublicKey(userId, publicKey);
    }
    const profile = await updateAccountProfile(userId, {
      username:
        username === undefined
          ? current.username
          : normalizeProfileUsername(username),
      avatarEmoji:
        avatarEmoji === undefined
          ? current.avatarEmoji
          : normalizeProfileAvatar(avatarEmoji),
    });
    res.json({ profile });
  } catch (error) {
    next(error);
  }
});

router.delete("/", async (req, res, next) => {
  const { userId } = getAuth(req);
  if (!userId) {
    res.status(401).json({ error: "Authentication required." });
    return;
  }

  try {
    disconnectAccountUser(userId, "deleted");
    await deleteAccount(userId);
    res.status(204).end();
  } catch (error) {
    next(error);
  }
});

export default router;
