import { Sentry, sentryEnabled } from "./sentry";
import { logger } from "./logger";
import { readPositiveIntEnv } from "./envTuning";
import type { ModerationActionKind } from "./moderationHistory";

/**
 * Alerting for a moderation action that took effect but could not be
 * written to the moderation log.
 *
 * The log is the audit trail for account access decisions, so a missing
 * entry is a fault someone has to know about — until now its only trace was
 * a server log line. The action itself has already succeeded by then, so
 * this never changes what the administrator's request answers; it only
 * makes the loss visible.
 */

/**
 * Which action, by whom, against whom: the three facts that say exactly
 * which entry the moderation log is now missing.
 *
 * Deliberately narrow — identifiers and the action kind only. Everything
 * here is attached to the Sentry event, so there is nowhere to put an email
 * address, a display name, or a configured value.
 */
export interface ModerationWriteFailureDetail {
  /** The action that took effect but went unrecorded. */
  action: ModerationActionKind;
  /** Clerk user id of the administrator who performed it. */
  actorUserId: string;
  /** Clerk user id of the account it was performed on. */
  targetUserId: string;
}

/** Sentry trims a tag value past 200 characters; truncate visibly instead. */
const MAX_TAG_VALUE_LENGTH = 200;

/**
 * Minimum time between two Sentry reports of a failed history write.
 *
 * A write fails because the database is unreachable or rejecting, which
 * lasts for as long as the outage does — every ban and restore attempted
 * meanwhile would file its own issue. One report per cooldown keeps that a
 * single actionable issue, the same way the Socket.IO rate alerts and the
 * readiness alert do, and is overridable by environment variable so it can
 * be retuned without a code change.
 *
 * The cooldown is held in memory rather than in the database the readiness
 * alert uses: the store would be the very thing that just failed, so it
 * could not be trusted to answer, and this fault is a live-event rate
 * rather than a standing configuration problem — a restart in the middle of
 * an outage should alert again.
 */
const WRITE_FAILURE_ALERT_COOLDOWN_MS = readPositiveIntEnv(
  "MODERATION_HISTORY_ALERT_COOLDOWN_MS",
  5 * 60_000,
);

/** When the last write failure was reported, or undefined if none was. */
let lastAlertAt: number | undefined;
/** Write failures the cooldown has swallowed since that report. */
let suppressedSinceLastAlert = 0;

/**
 * Trims a tag value to what Sentry keeps. The target account id arrives
 * from a request body, so its length is not this server's to assume.
 */
function tagValue(value: string): string {
  return value.length > MAX_TAG_VALUE_LENGTH
    ? `${value.slice(0, MAX_TAG_VALUE_LENGTH - 1)}…`
    : value;
}

/**
 * Reports a moderation action that could not be written to the history
 * table, as a Sentry issue in addition to the log line.
 *
 * Every failure is logged; the Sentry report is rate-limited by the
 * cooldown above, and the report that ends a cooldown says how many
 * failures it covered so the scale of the loss is not hidden by its own
 * throttling.
 *
 * Detail rides in tags, never in `extra`: Sentry's server-side scrubber
 * redacts an `extra` or context string whose value merely *mentions* a
 * credential word, which would leave a responder unable to tell a redacted
 * account id from one nobody sent. Tag values are left alone.
 */
export function reportModerationHistoryWriteFailure(
  error: unknown,
  detail: ModerationWriteFailureDetail,
): void {
  // The log keeps the whole picture — the driver error included, and the
  // repeats a cooldown leaves out. Nothing scrubs a pino line.
  logger.error({ err: error, ...detail }, "failed to record moderation action");

  if (!sentryEnabled) return;

  const now = Date.now();
  if (
    lastAlertAt !== undefined &&
    now - lastAlertAt < WRITE_FAILURE_ALERT_COOLDOWN_MS
  ) {
    suppressedSinceLastAlert += 1;
    return;
  }

  const tags: Record<string, string> = {
    // A stable class to search and alert on, independent of how the
    // underlying database error happens to word itself.
    moderationFailure: "history-write",
    moderationAction: tagValue(detail.action),
    moderationActorUserId: tagValue(detail.actorUserId),
    moderationTargetUserId: tagValue(detail.targetUserId),
  };
  if (suppressedSinceLastAlert > 0) {
    tags["moderationSuppressedFailures"] = String(suppressedSinceLastAlert);
  }

  // Recorded before the capture so a Sentry client that throws cannot turn
  // a standing outage back into one report per failed write.
  lastAlertAt = now;
  suppressedSinceLastAlert = 0;

  // The database error itself is the exception: it carries why the write
  // failed, which is what a responder needs beyond knowing that it did.
  Sentry.captureException(error, { tags });
}
