// Validate the NaCl secretbox wire format before storing or broadcasting data.
// Shape checks cannot prove a client actually encrypted its content, but they
// reject plain strings and malformed nonces instead of treating them as messages.
function canonicalBase64(value: string, minBytes: number, maxBytes: number): boolean {
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    return false;
  }
  const bytes = Buffer.from(value, "base64");
  return bytes.length >= minBytes && bytes.length <= maxBytes && bytes.toString("base64") === value;
}

export function isEncryptedMessagePayload(ciphertext: unknown, nonce: unknown): ciphertext is string {
  return (
    typeof ciphertext === "string" &&
    typeof nonce === "string" &&
    canonicalBase64(ciphertext, 17, 15_000) &&
    canonicalBase64(nonce, 24, 24)
  );
}