import { Sentry, sentryEnabled } from "./sentry";
import { logger } from "./logger";
import { readPositiveIntEnv } from "./envTuning";

/**
 * Supporting detail for a Socket.IO failure alert.
 *
 * The fields are fixed and narrow on purpose: identifiers and problem
 * classes only. Everything here is attached to the Sentry event, so there
 * is deliberately nowhere to put a configured value, a token, or key
 * material — not even "whatever might help" from a future caller.
 */
export interface SocketFailureDetail {
  /** Socket.IO connection id (`socket.id`) — per-connection, not an account. */
  sid?: string;
  /** Clerk user id of the authenticated member, when the failure has one. */
  userId?: string;
  /** Short problem class, e.g. "invalid_session" or "transport close". */
  reason?: string;
}

/** Sentry trims a tag value past 200 characters; truncate visibly instead. */
const MAX_TAG_VALUE_LENGTH = 200;

/**
 * Tag name for each detail field, namespaced so they group with
 * `socketEvent` in Sentry's tag list and cannot collide with a tag the SDK
 * sets itself (`url`, `environment`, ...).
 */
const DETAIL_TAG_NAMES: Record<keyof SocketFailureDetail, string> = {
  sid: "socketSid",
  userId: "socketUserId",
  reason: "socketReason",
};

/**
 * Turns failure detail into Sentry **tags** rather than `extra`.
 *
 * Sentry's server-side scrubber redacts an `extra` or context string whose
 * value merely *mentions* a credential word, anywhere inside it and in any
 * case: real events confirm that "auth", "secret", "password",
 * "credentials" and "privatekey" each replace the whole value, so
 * "user_authToken_9" and "someAuthValue" both arrive as "[Filtered]" with
 * nothing in the event to say it happened. Socket failures are exactly
 * where such words turn up — the handshake path, an identifier that
 * happens to contain one, a future reason like "auth_failed" — and the
 * responder cannot tell a redaction from a value nobody sent.
 *
 * Tag values are left alone, which is why the readiness alert already
 * carries its per-setting status that way.
 */
function detailTags(detail: SocketFailureDetail): Record<string, string> {
  const tags: Record<string, string> = {};
  for (const [field, value] of Object.entries(detail)) {
    const name = DETAIL_TAG_NAMES[field as keyof SocketFailureDetail];
    if (!name || typeof value !== "string" || value.length === 0) continue;
    tags[name] =
      value.length > MAX_TAG_VALUE_LENGTH
        ? `${value.slice(0, MAX_TAG_VALUE_LENGTH - 1)}…`
        : value;
  }
  return tags;
}

/**
 * Tracks how often an event happens within a rolling time window and raises
 * a single Sentry alert once the count crosses a threshold, then stays
 * quiet for a cooldown period. This turns a flood of individual failures
 * (e.g. every rejected handshake during a bad deploy) into one actionable
 * Sentry issue instead of one event per failure.
 */
class RateAlert {
  private readonly timestamps: number[] = [];
  private lastAlertAt = 0;

  constructor(
    private readonly options: {
      /** Human-readable label used in the Sentry message and log line. */
      label: string;
      /** Size of the rolling window, in milliseconds. */
      windowMs: number;
      /** Number of occurrences within the window that triggers an alert. */
      threshold: number;
      /** Minimum time between alerts, so a sustained spike files one issue, not one per event. */
      cooldownMs: number;
    },
  ) {}

  record(detail: SocketFailureDetail = {}): void {
    const now = Date.now();
    this.timestamps.push(now);
    const cutoff = now - this.options.windowMs;
    while (this.timestamps.length > 0 && this.timestamps[0]! < cutoff) {
      this.timestamps.shift();
    }

    if (
      this.timestamps.length < this.options.threshold ||
      now - this.lastAlertAt < this.options.cooldownMs
    ) {
      return;
    }

    this.lastAlertAt = now;
    const windowSeconds = Math.round(this.options.windowMs / 1000);
    const message = `${this.options.label}: ${this.timestamps.length} in the last ${windowSeconds}s`;
    // The log keeps the whole picture: nothing scrubs a pino line.
    logger.error({ ...detail, count: this.timestamps.length }, message);
    if (sentryEnabled) {
      Sentry.captureMessage(message, {
        level: "error",
        // The count rides in the message and the reason in a tag: the two
        // parts of an event the scrubber leaves alone. Nothing here goes
        // into `extra`, where a reason naming an auth state would be
        // redacted with no sign that anything was dropped.
        tags: detailTags(detail),
      });
    }
  }
}

// Defaults are deliberately conservative heuristics, not measured
// baselines -- this app has not run with real chat traffic long enough to
// know its normal auth-failure/disconnect rates. The goal is to catch a
// step-change (e.g. a bad deploy that rejects every handshake, or a crash
// loop that disconnects everyone) rather than to alert on ordinary
// day-to-day churn.
//
// Every value is overridable via environment variable so that once real
// production volume is observed, the alert can be retuned with a config
// change instead of a code change and redeploy.
const authFailureAlert = new RateAlert({
  label: "Elevated Socket.IO auth-failure rate",
  windowMs: readPositiveIntEnv("SOCKET_AUTH_FAILURE_ALERT_WINDOW_MS", 60_000),
  threshold: readPositiveIntEnv("SOCKET_AUTH_FAILURE_ALERT_THRESHOLD", 10),
  cooldownMs: readPositiveIntEnv(
    "SOCKET_AUTH_FAILURE_ALERT_COOLDOWN_MS",
    5 * 60_000,
  ),
});

const disconnectAlert = new RateAlert({
  label: "Elevated Socket.IO disconnect rate",
  windowMs: readPositiveIntEnv("SOCKET_DISCONNECT_ALERT_WINDOW_MS", 60_000),
  threshold: readPositiveIntEnv("SOCKET_DISCONNECT_ALERT_THRESHOLD", 30),
  cooldownMs: readPositiveIntEnv(
    "SOCKET_DISCONNECT_ALERT_COOLDOWN_MS",
    5 * 60_000,
  ),
});

/** Call whenever the connection middleware rejects a handshake. */
export function recordSocketAuthFailure(reason: string): void {
  authFailureAlert.record({ reason });
}

/** Call for every socket disconnect, regardless of reason. */
export function recordSocketDisconnect(reason: string): void {
  disconnectAlert.record({ reason });
}

/**
 * Reports a bug that broke a Socket.IO event handler (e.g. an unexpected
 * database error inside "join-room") as a Sentry issue in addition to the
 * pino log line, so it surfaces without relying on a user reporting dropped
 * chats.
 */
export function reportSocketHandlerError(
  event: string,
  error: unknown,
  detail: SocketFailureDetail = {},
): void {
  logger.error({ err: error, event, ...detail }, `Socket.IO "${event}" handler failed`);
  if (sentryEnabled) {
    // Tags only, no `extra`: see detailTags() for why the scrubber makes
    // `extra` an unreliable place for a socket failure's detail.
    Sentry.captureException(error, {
      tags: { socketEvent: event, ...detailTags(detail) },
    });
  }
}
