import { verifyWebhook } from "@clerk/express/webhooks";
import { Router } from "express";
import { syncModeratorProfileAfterIdentityChange } from "../lib/accountProfile";
import { inspectClerkWebhookSigningSecret } from "../lib/clerkWebhookSecret";

// Single source of truth for where Clerk delivers webhooks, relative to the
// API router's mount point (API_MOUNT_PATH in routes/index.ts). app.ts
// derives the raw-body parser path from both constants, so renaming the
// route here cannot leave the parser behind on a stale path and hand the
// verifier a re-serialized body.
export const CLERK_WEBHOOK_ROUTE = "/webhooks/clerk";

const router = Router();

router.post("/", async (req, res, next) => {
  let event;
  // A value that is present but not a usable Svix secret would fail every
  // signature check, so treat it like no configuration at all instead of
  // reporting a per-delivery signature problem the sender cannot fix.
  const secret = inspectClerkWebhookSigningSecret();
  if (secret.status !== "ok") {
    res.status(503).json({ error: "Webhook verification is not configured." });
    return;
  }

  try {
    event = await verifyWebhook(req, { signingSecret: secret.signingSecret });
  } catch {
    res.status(400).json({ error: "Invalid webhook signature." });
    return;
  }

  if (event.type !== "user.updated") {
    res.status(200).json({ received: true });
    return;
  }

  try {
    await syncModeratorProfileAfterIdentityChange(event.data.id);
    res.status(200).json({ received: true });
  } catch (error) {
    next(error);
  }
});

export default router;
