import { clerkClient } from "@clerk/express";
import { clerkRetryDelayMs } from "./clerkRetry";
import { isGrantedModerator } from "./moderatorStore";

const ACCESS_METADATA_KEY = "devStudioAccess";
const pendingAccessChecks = new Map<string, Promise<AccountAccess>>();

export type AccountAccess =
  { allowed: true } | { allowed: false; reason: "banned" | "unverified" };

function getRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function isBanned(privateMetadata: Record<string, unknown>): boolean {
  return getRecord(privateMetadata[ACCESS_METADATA_KEY])?.["banned"] === true;
}

export function isAccountBanned(
  privateMetadata: Record<string, unknown>,
): boolean {
  return isBanned(privateMetadata);
}

export interface ClerkIdentity {
  primaryEmailAddressId: string | null;
  emailAddresses: Array<{
    id: string;
    emailAddress: string;
    verification: { status: string | null } | null;
  }>;
}

export function verifiedPrimaryEmail(user: ClerkIdentity): string | null {
  const primaryEmail = user.emailAddresses.find(
    (emailAddress) => emailAddress.id === user.primaryEmailAddressId,
  );
  return primaryEmail?.verification?.status === "verified"
    ? primaryEmail.emailAddress
    : null;
}

async function loadAccountAccess(userId: string): Promise<AccountAccess> {
  let user: Awaited<ReturnType<typeof clerkClient.users.getUser>>;
  for (let attempt = 0; ; attempt += 1) {
    try {
      user = await clerkClient.users.getUser(userId);
      break;
    } catch (error) {
      const delayMs = clerkRetryDelayMs(error, attempt);
      if (delayMs === null || attempt >= 3) throw error;
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }
  const email = verifiedPrimaryEmail(user);
  if (isBanned(user.privateMetadata) && !(await isAdmin(userId))) {
    return { allowed: false, reason: "banned" };
  }
  return email ? { allowed: true } : { allowed: false, reason: "unverified" };
}

export async function getAccountAccess(userId: string): Promise<AccountAccess> {
  const existing = pendingAccessChecks.get(userId);
  if (existing) return existing;

  const pending = loadAccountAccess(userId);
  pendingAccessChecks.set(userId, pending);
  try {
    return await pending;
  } finally {
    if (pendingAccessChecks.get(userId) === pending) {
      pendingAccessChecks.delete(userId);
    }
  }
}

export async function setAccountBan(
  userId: string,
  banned: boolean,
): Promise<void> {
  const user = await clerkClient.users.getUser(userId);
  if (banned && (await isAdmin(userId))) {
    throw new Error("Administrator accounts cannot be banned.");
  }
  const existingAccess =
    getRecord(user.privateMetadata[ACCESS_METADATA_KEY]) ?? {};
  await clerkClient.users.updateUserMetadata(userId, {
    privateMetadata: {
      ...user.privateMetadata,
      [ACCESS_METADATA_KEY]: {
        ...existingAccess,
        banned,
        ...(banned
          ? { bannedAt: new Date().toISOString() }
          : { bannedAt: null }),
      },
    },
  });
}

/**
 * The bootstrap moderator list from ADMIN_USER_IDS. Read at call time so a
 * configuration change is picked up without a restart.
 */
export function configuredAdminIds(): string[] {
  return (process.env["ADMIN_USER_IDS"] ?? "")
    .split(",")
    .map((id) => id.trim())
    .filter(Boolean);
}

/** Whether this account moderates because it is in the bootstrap list. */
export function isConfiguredAdmin(userId: string): boolean {
  return configuredAdminIds().includes(userId);
}

/**
 * Whether this account can moderate at all: from the ADMIN_USER_IDS
 * bootstrap list, or from the database allow-list managed in the moderation
 * panel. The bootstrap list is checked first so the moderation tools stay
 * reachable even if the allow-list cannot be read.
 */
export async function isAdmin(userId: string): Promise<boolean> {
  return isConfiguredAdmin(userId) || (await isGrantedModerator(userId));
}
